WITH payload AS (SELECT $archive_payload$[{"id":"63fadcb2-5c7f-5d46-8f00-24aa94dacd51","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة بأجرة زادت عن مدة العقد -تخلف املدعى عليه عن احلضور رغم تبلغه ،تقدير األجرة عن طريق قسم اخلبراء- إلزام املدعى عليه بدفع األجرة وفق تقدير قسم اخلبراء -اعتبار احلكم حضوريا لتبلغ املدعى عليه -تنفيذ احلكم.","document_number":"33351548","case_number":"3381431","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/22","year":"1434","subject":"إجارة -مطالبة بأجرة زادت عن مدة العقد -تخلف املدعى عليه عن احلضور رغم تبلغه ،تقدير األجرة عن طريق قسم اخلبراء- إلزام املدعى عليه بدفع األجرة وفق تقدير قسم اخلبراء -اعتبار احلكم حضوريا لتبلغ املدعى عليه -تنفيذ احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/7/22:‬هـ‬\n                 ‫ُ‬               ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪33351548 :‬‬\n                   ‫َر ْق ُم الدعوى‪3381431 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 3410769‬تاريخه‪1434/1/13:‬هـ‬\n\n\n‫إجــارة ‪ -‬مطالبــة بأجــرة زادت عــن مــدة العقــد‪ -‬تخلــف املدعــى عليــه‬\n‫عــن احلضــور رغــم تبلغــه‪ ،‬تقديــر األجــرة عــن طريــق قســم اخلبــراء‪-‬‬\n‫إلــزام املدعــى عليــه بدفــع األجــرة وفــق تقديــر قســم اخلبــراء‪ -‬اعتبــار‬\n                 ‫احلكــم حضوريــا لتبلــغ املدعــى عليــه ‪ -‬تنفيــذ احلكــم‪.‬‬\n\n\n\n\n                                   ‫‪ -1‬القاعدة الفقهية «ال ضرر وال ضرار»‪.‬‬\n                               ‫‪ -2‬املادة (‪ )1/55‬من نظام املرافعات الشرعية‪.‬‬\n                               ‫‪ -3‬املادة (‪ )4/56‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن  املدعــى عليــه اســتأجر منــه ورشــة بســبعني ألــف‬\n‫ريــال للســنة الواحــدة وانتهــت املــدة ولــم يقــم بتجديــد العقــد وال إخالئهــا‬\n‫ويطلــب احلكــم عليــه بدفــع أجــرة فتــرة بقائــه يف الورشــة وقدرهــا‬\n‫بعشــرين ألــف ريــال للشــهر الواحــد ‪ -‬لــم يحضــر املدعــى عليــه بعــد‬\n‫تبلغــه فجــرى الســير يف الدعــوى غيابيــا ‪ -‬جــرى االطــاع علــى وثيقــة‬\n‫العقــد املبرمــة بــن الطرفــن ‪ -‬جــرى ســؤاله عــن صــك ملكيتــه للورشــة‬\n‫فقــرر بأنــه اشــتراها مــن املالــك ولــم تفــرغ لــه بعــد وأبــرز وثيقــة شــرائه‬\n‫للورشــة‪ -‬جــرى الكتابــة لقســم اخلبــراء لإلفــادة عــن أجــرة املثــل فأفادت‬\n                                                                                        ‫‪214‬‬\n\f      ‫بــأن األجــرة تقــدر بخمســة وثمانــن ألــف ريــال للســنة الواحــدة وبعرضــه‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى‬  ‫علــى املدعــي قــرر قناعتــه بــه ‪ -‬فبنـ ً‬\n      ‫واالطــاع علــى عقــد االيجــار وعلــى عقــد املبايعــة وعلــى محاضــر تبليــغ‬\n      ‫املدعــى عليــه ومبــا أن املدعــى عليــه تبلــغ مبوعــد اجللســة ولــم يحضــر‬\n      ‫ا عــن احلضــور والشــارع احلكيــم أزال الضــرر عــن‬        ‫ممــا يعتبــر مماط ـ ً‬\n      ‫املتضــرر فــا ضــرر وال ضــرار ملــا ســبق كلــه فقــد صــدر احلكــم علــى‬\n      ‫املدعــى عليــه بســداد أجــرة عقــار املدعــي حــا ًال وقدرهــا اثنــان وخمســون‬\n      ‫ألفــا وخمســمائة ريــال قيمــة األجــرة لألشــهر الســبعة املاضيــة وهــذا‬\n      ‫احلكــم يف حقــه يعتبــر حضوريـ ًا اســتناد ًا إلــى املــادة (‪ )1/55‬مــن نظــام‬\n      ‫املرافعــات الشــرعية وتقــرر تزويــده بنســخة مــن هــذا احلكــم اســتناد ًا‬\n      ‫إلــى املــادة ‪ 4/56‬مــن ذات النظــام ‪ -‬برفعــه حملكمــة االســتئناف عــادت‬\n                                             ‫القضيــة مصدقــة ‪ -‬مت تنفيــذ احلكــم‪.‬‬\n\n\n\n\n        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....................‬القاضــي يف احملكمــة‬\n        ‫العامــة ببريــدة   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫محاكــم منطقــة القصيــم برقــم ‪ 3381431‬وتاريــخ ‪ 1433/02/01‬هــ  ‬\n        ‫املقيــدة باحملكمــة برقــم ‪ 33214234‬وتاريــخ ‪ 1433/2/1‬ه ـ املتعلقــة‬\n      ‫بدعــوى ‪ ......................‬ضــد ‪ ....................‬بخصــوص أجــرة عقــار عليــه  ‬\n        ‫ففــي يــوم االثنــن املوافــق‪ 1433/02/22‬ه ـ أفتتحــت اجللســة الســاعة‬\n        ‫‪  10 : 50‬وفيهــا حضــر  ‪   ........................‬ســعودي  اجلنســية مبوجــب‬\n        ‫الســجل املدنــي رقــم    ………………‪  .‬ولــم يحضــر املدعــى عليــه مــع‬\n        ‫تبلغــه لشــخصه مبوجــب خطابنــا رقــم ‪ 33111852‬يف ‪1433/1/17‬ه ـ‬\n‫‪215‬‬\n\f‫واســتنادا إلــى املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية فقــد جــرى رفــع‬\n‫اجللســة ويف يــوم الســبت ‪1433/3/12‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي ولــم يحضــر املدعــى عليــه وقــد قــدم املدعــى عليــه االســتدعاء‬\n‫الــوارد إلينــا مــن فضيلــة الرئيــس برقــم ‪ 33/452248‬يف ‪1433/3/8‬ه ـ‬\n‫املتضمــن اعتــذاره حلضــور اجللســة وطلبــه تأجيــل املوعــد ملــدة ثالثــن يوم َا‬\n‫وقــد ســبق أن تبلــغ املدعــى عليــه حلضــور اجللســات عدة مــرات ولم يحضر‬\n‫ا لــذا فــإن عــذره اليقبــل وقــد جــرى ســؤال املدعــي عــن‬  ‫ممــا يعــد مماطـ ً‬\n‫دعــواه فقــال أدعــي علــى الغائــب عــن مجلــس احلكــم ‪......................‬‬\n‫بأنــه بتاريــخ ‪1430/1/6‬ه ـ أجرتــه الورشــة اململوكــة لــي يف صناعيــة ‪...‬‬\n‫ببريــدة ملــدة ثــاث ســنوات تبــدأ مــن تاريــخ ‪1430/1/1‬ه ـ وتنتهــي بتاريــخ‬\n‫‪1433/1/1‬ه ـ وقــد انتهــت املــدة ولــم يخلــي العقــار وقــد دخلــت عليــه‬\n‫ســنة جديــدة وهــي ســنة ‪1433/1/1‬ه ـ وحتــى تاريــخ هــذه اجللســة جلــس‬\n‫فيهــا قرابــة ثالثــة أشــهر ومبــا أن العقــد منتهــي فيحســب جلوســه يف‬\n‫الورشــة بأجــرة جديــدة للشــهر الواحــد مببلــغ وقــدره عشــرون ألــف ريــال‬\n‫وقــد حــل عليــه اآلن ثالثــة أشــهر مببلــغ وقــدره ســتون ألــف ريــال أطلــب‬\n‫احلكــم عليــه وإلزامــه بســداد هــذه األجــرة هــذه دعــواي وحيــث األمــر‬\n‫ماذكــر طلبــت مــن املدعــي عقــد اآلجــار فأبــرز لــي العقــد الصــادر‬\n‫مــن مكتــب ‪ ......‬العقــاري برقــم ‪ 1073‬يف ‪1430/1/6‬ه ـ املتضمــن أن‬\n‫املســتأجر ‪ ...........‬رقــم احلفيظــة ‪ ........‬تاريخهــا ‪1414/5/30‬ه ـ بعــون‬\n‫اهلل مت االتفــاق بــن كل مــن ‪ .........‬طــرف أول والســيد ‪ ............‬طــرف‬\n‫ثانــي علــى أن يســتأجر الطــرف الثانــي عقــار الطــرف األول وهــو عبــارة‬\n‫عــن ورشــة كاملــة يف صناعيــة الصانــع مــدة اإليجــار ثــاث ســنوات‬\n‫تبــدأ من‪1430/1/1‬هــ   وتنتهــي يف ‪1433/1/1‬ه ـ وتكــون األجــرة‬\n\n\n                                                                                      ‫‪216‬‬\n\f        ‫مببلــغ ســبعون ألــف ريــال للســنة الواحــدة واملوقــع مــن ‪ .....‬واملدعــى‬\n        ‫عليــه ‪ .......‬وختــم املكتــب العقــاري وحيــث األمــر ماذكــر قــررت‬\n        ‫الكتابــة لقســم اخلبــراء بهــذه احملكمــة لإلفــادة عــن مقــدار األجــرة‬\n      ‫للورشــة املذكــورة لــذا جــرى رفــع اجللســة حلــن ورود اإلجابــة ويف يــوم  ‬\n        ‫الثالثــاء املوافــق‪ 1433/07/22‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n        ‫والنصــف صباحــا وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه مــع‬\n        ‫تبلغــه لشــخصه مبوجــب خطابنــا رقــم ‪ ...‬يف ‪1433/6/30‬ه ـ جرى ســؤال‬\n        ‫املدعــى عــن دعــواه  فادعــى املدعــي قائــا يف تقريــر دعــواه ضــد الغائــب‬\n        ‫عــن مجلــس احلكــم ‪ .........‬إنــه بتاريــخ ‪1430/1/1‬ه ـ أجرتــه املجمــع‬\n        ‫اخلــاص بــي والواقــع يف صناعيــة ‪ ......‬ببريــدة واســتأجر منــي املدعــى عليه‬\n        ‫هــذا املجمــع ملــدة ثــاث ســنوات تبــدأ مــن تاريــخ ‪1430/1/1‬ه ـ بأجــرة‬\n        ‫ســنوية قدرهــا ســبعون ألــف ريــال تنتهــي بتاريــخ ‪1433/1/1‬ه ـ وانتهــى‬\n        ‫عقــد اإليجــار ولــم نتفــق علــى جتديــده وقــد ســلمني األجــرة املاضيــة‬\n        ‫ودخلــت عليــه ســنة جديــدة بأجــرة جديــدة وحيــث حــل عليــه اآلن ســبعة‬\n        ‫أشــهر مــن تاريــخ ‪1433/1/1‬هــ  أطلــب إلزامــه بســداد األجــرة التــي‬\n        ‫حلــت عليــه وقدرهــا عشــرون ألــف ريــاال شــهريا حيــث إن اآليجــارات‬\n        ‫اآلن ارتفعــت وعليــه فيكــون مجمــوع مــا أطالبــه بــه مبلغــا وقــدره مائــة‬\n        ‫واربعــون ألــف ريــال أطلــب احلكــم عليــه وتســليمه لــي حــاالً‪ ،‬هــذه‬\n        ‫دعــواي‪ ،‬هكــذا ادعــى املدعــي‪ .‬وحيــث األمــر ماذكــر طلبــت مــن‬\n        ‫املدعــي عقــد اآليجــار  فأبــرزه لــي وهــو العقــد الصــادر مــن مكتــب‬\n        ‫‪ ...........‬العقــاري برقــم ‪ 1073‬يف ‪1430/1/6‬ه ـ ‪ .‬املتضمــن أن املســتأجر‬\n        ‫‪ .................‬رقــم احلفيظــة ‪ ..............‬تاريخهــا ‪1414/5/30‬ه ـ بعــون اهلل‬\n        ‫مت االتفاق بني كل من ‪....................‬طرف أول والسيد ‪........................‬‬\n\n\n‫‪217‬‬\n\f‫طــرف ثانــي علــى أن يســتأجر الطــرف الثانــي عقــار الطــرف األول وهــو‬\n‫عبــارة عــن ورشــة كاملــة يف صناعيــة ‪ ...‬مــدة اإليجــار ثــاث ســنوات‬\n‫تبــدأ مــن ‪1430/1/1‬هــ  وتنتهــي يف ‪1433/1/1‬ه ـ وتكــون األجــرة‬\n‫مببلــغ ســبعون ألــف ريــال للســنة الواحــدة واملوقــع مــن ‪ ...........‬واملدعــى‬\n‫عليــه ‪.............‬وختــم املكتــب العقــاري جــرى ســؤاله عــن صــك التملــك‬\n‫فقــال إنــه لــم يفــرغ لــي وإمنــا يوجــد معــي عقــد مبايعــة ثــم أبــرزه لــي وهــذا‬\n‫نصــه عقــد مبايعــة (صناعيــة ‪ ............‬ببريــدة ) عقــد بيــع ورشــة بســم اهلل‬\n‫والصــاة والســام علــى رســول اهلل ‪ .‬فقــد مت بعــون اهلل تعالــى االتفــاق‬\n‫يــوم ‪1425/4/1‬ه ـ املوافــق ‪2004/5/30‬م بــن كل مــن الطرفــن‬\n‫الطــرف األول البائــع ‪ .................:‬ســجل جتــاري رقــم ‪ ..............‬وميثلهــا‬\n‫نائــب املديــر ‪ ..............‬الطــرف الثانــي املشــتري ‪...............‬ســجل مدنــي‬\n‫رقــم ‪ ..................‬املدينــة بريــدة هاتــف ‪ .................‬علــى مايلــي ‪ :‬أو ًال‬\n‫بــاع الطــرف األول علــى الطــرف الثانــي ورشــة ‪ 95‬الواقعــة يف مخطــط‬\n‫صناعية ‪ ...‬ببريدة اململوك له برقم ‪ 1127/2‬ق شــاملة األرض وماعليها‬\n‫مــن منشــآت وذلــك بقيمــة إجماليــة صافيــة مبلــغ وقــدره ‪445,000,00‬‬\n‫ر‪.‬س فقــط ‪.‬فقــط أربعمائــة وخمســة وأربعــون ألــف ريــال الغيــر يضــاف‬\n‫عليهــا عمولــة بنســبة ‪ %2,5‬فقــط ســعي مســاحة الورشــة فقــط ‪ 396‬متــر‬\n‫وحدودهــا كالتالــي يحدهــا مــن الشــمال شــارع عــرض ‪25‬م بطــول‬\n‫‪19,85‬م يحدهــا مــن اجلنــوب عمــارة رقــم ‪ 13‬بطــول ‪19,85‬م يحدهــا‬\n‫مــن الشــرق ورشــة رقــم ‪ 96‬بطــول ‪19,82‬م يحدهــا مــن الغــرب ورشــة‬\n‫رقــم ‪94‬بطــول ‪ 19,82‬م وحتتــوي الورشــة علــى محــات عددهــا ‪ 2‬محــل‬\n‫وهــي مؤجــرة بقيمــة إيجاريــة ســنوية مقدارهــا(‪ . )....‬ثانيـ ًا عايــن الطــرف‬\n‫الثانــي ( املشــتري) ‪ :‬العــن ورضــى بهــا خاليــة مــن الشــوائب كمــا وســدد‬\n\n\n                                                                                             ‫‪218‬‬\n\f       ‫الطــرف الثانــي ( املشــتري) للطــرف األول ( البائع)‪.‬ماقيمتــه خمــس‬\n       ‫وتســعون باملئــة ‪%95‬مــن قيمــة العقــار وذلــك طبق ـ ًا لآلتــي القيمــة شــيك‬\n       ‫رقــم ‪217‬تاريــخ ‪1425/5/11‬ه ـ مببلــغ ‪ 100,000,00‬ر‪.‬س علــى بنــك ‪...‬‬\n       ‫ومبلــغ وقــدره‪ 226.994.00‬خصمنــا مــن مســاهمته معنــا مبوجــب ســند‬\n       ‫املســاهمة رقــم‪ 9,97‬ويســلم املســاهم مســاهمته و ربحهــا أو املتبقــي منهــا‬\n       ‫عنــد التصفيــة النهائيــة للمســاهمة‪ .‬ثالثـ ًا ‪ :‬العبــرة يف األطــوال واملســاحة‬\n       ‫هي الطبيعة التي عاينها املشتري وقبل بها ‪ .‬رابع ًا ‪ :‬يف حال عدم صرف‬\n       ‫الشــيك املقــدم مــن الطــرف الثانــي ألي ســبب فيعتبــر البيــع الغي ًا واليحق‬\n       ‫لــه املطالبــة بالعــن العقاريــة خامســا‪:‬اليحق للمشــتري املطالبــة بقســط‬\n      ‫اإليجــار الــذي حــل واســتلم قبــل هــذا العقــد ألنــه مــن حــق املســاهمني ‬\n       ‫ويدخــل يف أربــاح املســاهمة ‪ .‬مالحظــة يتــم تســديد املبلــغ املتبقــي مــن‬\n       ‫قيمــة العقــار والــذي يســاوي ‪ %5‬مــن اجمالــي القيمــة عنــد اإلفــراغ  ‪.‬‬\n       ‫مالحظــة ‪ :‬يتــم تســديد مبلــغ الســعي بواقــع ‪ % 2.5‬مــن اجمالــي قيمــة‬\n       ‫العقــار عنــد اإلفــراغ ‪ .‬ال يحــق ملالكــي ومســتأجري الــورش اســتخدام‬\n       ‫االرتــداد بــن الــورش والعمائــر ( الشــركة ليســت مســؤولة عــن ادخــال‬\n       ‫الكهربــاء وامليــاه للعــن املباعــة وال عــن تكاليفهــا ويتــم اإلفــراغ حســب‬\n       ‫مواعيــد كتابــة العــدل ‪ .‬الطــرف األول ‪ ...‬البائــع شــركة ‪ ...‬الوكيــل‬\n       ‫الطــرف الثانــي املشــتري ‪ ...............‬توقيعــه) كمــا جــرت الكتابــة منــا‬\n       ‫لقســم اخلبــراء بخطابنــا رقــم ‪ 33/214234‬يف ‪1433/3/12‬ه ـ لإلفــادة‬\n       ‫عــن قيمــة اإليجارفوردنــا خطابهــم رقــم ‪ 33214234‬يف ‪1433/6/7‬ه ـ‬\n       ‫واملرفــق بــه محضــر هيئــة النظــر املتضمــن أنــه مت الوقــوف علــى العقــار‬\n       ‫املذكــور وهــو عبــارة عــن ورشــة ومحلــن وســكن عمــال وبعــد النظــر‬\n       ‫فيهــا ويف موقعهــا مــن الصناعيــة ورأي أهــل اخلبــرة مــن أهــل العقــارات‬\n\n\n‫‪219‬‬\n\f  ‫فــإن هــذه الورشــة تقــدر قيمــة ايجارهــا مــن خمســة وثمانــن ألــف ريــال‬\n  ‫إلــى مائــة ألــف ريــال وتــرى الهيئــة أن قيمــة أجرتهــا الشــهرية ســبعة آالف‬\n  ‫ـاء علــى‬‫وخمســمائة ريــال وبعــرض ذلــك علــى املدعــي قــرر قناعتــه ‪ .‬فبنـ ً‬\n‫ماتقــدم مــن الدعــوى واالطــاع علــى عقــد االيجــار وعلــى عقــد املبايعــة  ‬\n  ‫وعلــى محاضــر تبليــغ املدعــى عليــه ومبــا أن املدعــى عليــه تبلــغ مبوعــد‬\n  ‫ا عــن احلضــور والشــارع احلكيــم‬     ‫اجللســة ولــم يحضــر ممــا يعتبــر مماطـ ً‬\n  ‫أزال الضــرر عــن املتضــرر فــا ضــرر وال ضــرار ملــا ســبق كلــه فقــد‬\n  ‫حكمــت علــى املدعــى عليــه ‪ ................‬بســداد أجــرة عقــار املدعــي حا ًال‬\n  ‫وقدرهــا اثنــان وخمســون ألفــا وخمســمائة ريــال قيمــة األجــرة لألشــهر‬\n  ‫الســبعة املاضيــة وهــذا احلكــم يف حقــه يعتبــر حضوري ـ ًا اســتناد ًا إلــى‬\n  ‫املــادة (‪ )1/55‬مــن نظــام املرافعــات الشــرعية وقــررت تزويده بنســخة من‬\n  ‫هــذا احلكــم اســتناد ًا إلــى املــادة ‪ 4/56‬مــن ذات النظــام وبــاهلل التوفيــق‬\n  ‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/7/22‬ه ـ احلمــد‬\n  ‫هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1434/2/5‬ه ـ أفتتحــت اجللســة وقــد‬\n  ‫وردتنــا املعاملــة مــن  محكمــة اإلســتئناف بالقصيــم رفــق خطــاب فضيلة‬\n  ‫رئيســها رقــم ‪ 332250537‬يف ‪1434/1/20‬ه ـ املتضمــن املصادقــة علــى‬\n  ‫احلكــم الصــادر منــا برقــم ‪ 33351548‬يف ‪1433/7/22‬ه ـ وذلــك‬\n  ‫مبوجــب القــرار الصــادر منهــم  برقــم‪ 34 10769‬يف ‪1434/1/13‬ه ـ‬\n  ‫وللمعلوميــة جــرى تدوينــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                    ‫محمــد حــرر يف ‪1434/2/5‬ه ـ‬\n  ‫احلمــد هلل وحــده وبعــد ويف يــوم األثنــن املوافــق ‪1434/4/1‬ه ـ أفتتحــت‬\n  ‫اجللســة وفيهــا حضــر املدعــي‪ .........‬وقــرر وهــو بحالتــه املعتبــرة شــرع ًا‬\n  ‫أنــه اســتلم كامــل املبلــغ احملكــوم لــه بعاليــه وذلــك مبوجــب الشــيك‬\n\n\n                                                                                        ‫‪220‬‬\n\f      ‫املســحوب علــى مصــرف ‪ .........‬برقــم ‪ 636677‬يف ‪2013/1/27‬م فــرع‬\n      ‫‪ ...‬واملمثــل ملبلــغ وقــدره اثنــان وخمســون ألف ـ ًا وخمســمائة ريــال ‪ ،‬وذلــك‬\n      ‫عــن ذمــة املدعــى عليــه ‪ ....................‬وبهــذا اإلســتالم ال يطالــب أحدهمــا‬\n      ‫ال بخصــوص هــذه القضيــة وأمــرت بإضافة‬       ‫اآلخــر ال حاضــر ًا وال مســتقب ً‬\n      ‫ماذكــر علــى صــك احلكــم وســجله حتــى ال يخفــى ‪،‬وبــاهلل التوفيــق‬\n                  ‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/4/1‬ه ـ‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":214,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8b289ad752be123be4c6dcdfb215b28de0a96819a520f57307bea58bf3eba335","normalized_text_hash":"490298e8a3c8a291e5f72bb5fc3e9bf9ac72dc2a0b63443da2c8ef290f43770c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p214-33351548"},{"id":"beea0ec9-956c-591f-a3ff-1e2a8d609124","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة غير مكتوبة -استرداد أجرة مدفوعة -ما خسره ألجل نقل األثاث -املعروف عرفا كاملشروط شرط ا -تستقر األجرة بالتمكن من االنتفاع ولو لم ينتفع حقيقة -صرف النظر عن الدعوى.","document_number":"3440021","case_number":"3414824","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/18","year":"1434","subject":"إجارة غير مكتوبة -استرداد أجرة مدفوعة -ما خسره ألجل نقل األثاث -املعروف عرفا كاملشروط شرط ا -تستقر األجرة بالتمكن من االنتفاع ولو لم ينتفع حقيقة -صرف النظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/18 :‬هـ  ‬\n                  ‫ُ‬                 ‫َر ْق ُم َّ‬\n                       ‫الص ِّك‪3440021 :‬‬\n                    ‫َر ْق ُم الدعوى‪  3414824 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34211085‬تاريخه‪1434/5/12 :‬هـ‬\n\n\n‫إجــارة غيــر مكتوبــة ‪ -‬اســترداد أجــرة مدفوعــة ‪ -‬مــا خســره ألجــل نقــل‬\n‫األثــاث ‪ -‬املعــروف عرفــا كاملشــروط شــرط ًا ‪ -‬تســتقر األجــرة بالتمكــن‬\n    ‫مــن االنتفــاع ولــو لــم ينتفــع حقيقــة‪ -‬صــرف النظــر عــن الدعــوى‪.‬‬\n\n\n\n\n                 ‫‪ .1‬القاعدة الفقهية «املعروف عرفا كاملشروط شرطا»‪.‬‬\n‫‪ .2‬قول العالمة منصور البهوتي يف كشاف القناع (‪« :)145/9‬وتستقر‬\n‫األجــرة مبضــي املــدة حيــث ســلمت لــه العــن التــي وقعــت اإلجــارة عليهــا‬\n                                ‫وال حاجــز لــه عــن االنتفــاع ولــو لــم ينتفع»‪.‬‬\n\n\n\n\n‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه اســتأجر منــه شــقة ملــدة‬\n‫ســنة دفــع األجــرة كاملــة مقدمــا وبعــد ســتة أشــهر تقريبــا قــام املدعــى‬\n‫عليــه بســبه وشــتمه وطلــب منــه إخــاء الشــقة ووعــده بــرد حقــه وقــد‬\n‫تضــرر منــه لــذا يطلــب احلكــم عليــه بإعــادة مــا دفعــه كامــا وإلزامــه‬\n‫بدفــع أجــرة نقــل أثاثــه مــن الشــقة ومــا خســره بســبب الشــقة‪ ،‬أقــر‬\n‫ا وأنــه طلــب منــه‬ ‫املدعــى عليــه بعقــد األجــرة وتســليم ثمنهــا كام ـ ً‬\n‫إخالئهــا لتهربــه مــن التوقيــع علــى وثيقــة العقــد وتغييــره يف الشــقة دون‬\n\n                                                                                     ‫‪226‬‬\n\f      ‫إذنــه ولــم يخــرج مــن الشــقة حتــى تاريــخ إقامــة الدعــوى وال عالقــة لــه‬\n      ‫مبــا دفعــه لنقــل أثاثــه وتركيبــه عرفــا ‪ -‬أقــر املدعــي بأنــه لــم يوقــع معــه‬\n      ‫وثيقــة العقــد بعــد وأنــه ال زال يف الشــقة ويرفــض تســليمها لــه حتــى يــرد‬\n      ‫لــه كل مــا دفعــه مــن ثمــن األجــرة ومــا غرمــه لنقــل أثاثــه ونحــوه ‪ -‬عليــه‬\n      ‫وألن املدعــي يطالــب بإرجــاع أجــرة الشــقة‪ ،‬وإلقــراره بأنــه ال زال يف‬\n      ‫الشــقة حتــى اآلن ولدفــع املدعــى عليــه بعــدم حتمــل املؤجــر تكاليــف‬\n      ‫نقــل األثــاث وتركيبــه وللقاعــدة الفقهيــة املعــروف عرفــا كاملشــروط‬\n      ‫شــرطا ‪ ،‬وملــا ذكــره أهــل العلــم باســتحقاق األجــرة مبضــي املــدة كمــا‬\n      ‫قــال العالمــة منصــور البهوتــي يف كشــاف القنــاع (‪ « )145/9‬وتســتقر‬\n      ‫األجــرة مبضــي املــدة حيــث ســلمت لــه العــن التــي وقعــت اإلجــارة عليهــا‬\n      ‫وال حاجــز لــه عــن االنتفــاع ولــو لــم ينتفــع» صــدر احلكــم بصــرف النظــر‬\n      ‫عــن دعــوى املدعــي واخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى‪ -‬قــرر‬\n      ‫املدعــي االعتــراض بالئحــة وأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن‬\n                                                                ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬املــازم القضائي لدى الشــيخ (‪)....‬‬\n      ‫القائــم بعمــل الشــيخ (‪ )....‬القاضــي يف احملكمــة العامــة باملدينــة املنــورة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫باملدينــة املنورة‪/‬املســاعد برقــم ‪ 3414824‬وتاريــخ ‪1434/01/10‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 3469613‬وتاريــخ ‪1434/01/10‬ه ففــي يــوم‬\n      ‫األحــد املوافــق ‪1434/02/17‬ه ـ حضــر املدعــي (‪ )....‬ســعودي اجلنســية‬\n      ‫بالســجل املدنــي رقــم (‪ )....‬وادعــى علــى احلاضــر معــه (‪ )....‬ســعودي‬\n‫‪227‬‬\n\f‫ا إن هــذا احلاضــر اســتأجرت‬    ‫اجلنســية بالســجل املدنــي رقــم (‪ )....‬قائ ـ ً‬\n‫منــه شــقة مــن عمارتــه الواقعــة يف حــي (‪ )....‬بتاريــخ ‪1433/3/1‬ه ـ ملــدة‬\n‫ا لكــن‬   ‫ســنة‪ ،‬مببلــغ وقــدره خمســة وثالثــون ألــف ريــال دفعتــه كام ـ ً‬\n‫لــم نكتــب عقــد اإليجــار ويف العشــر األواخــر شــتمني وهددنــي وطلــب‬\n‫منــي اخلــروج ووعدنــي بإعطائــي حقــي وقــد تضــررت منــه فأنــا أطلــب‬\n‫منــه إرجــاع كامــل مبلــغ اإليجــار الــذي أخــذه منــي ويدفــع لــي مبلــغ‬\n‫قــدره خمســة عشــر ألــف ريــال مقابــل تكاليــف نقــل العفــش وتكاليــف‬\n‫األثــاث التــي خســرتها بســبب هــذه الشــقة هــذه دعــواي وبعــرض الدعــوى‬\n‫علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي مــن اســتأجرا الشــقة‬\n‫ودفــع اإليجــار كامــا فصحيــح وأمــا اخلــروج فقــد طلبــت منــه إخــاء‬\n‫الشــقة يف رمضــان ألنــه تهــرب عــن كتابــة العقــد وغيــر يف الشــقة مــن‬\n‫دون إذنــي ولــم يخــرج حتــى هــذه اللحظــة ومســألة نقــل العفــش واألثــاث‬\n‫وتركيبــه ال عالقــة لــي بــه كمــا هــو معــروف عند النــاس هكذا أجاب‬\n‫‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب بقولــه صحيــح أنــي قلــت نكتــب‬\n‫العقــد فيمــا بعــد ولــم نكتبــه حتــى اآلن والزلــت موجــودا يف الشــقة حتــى‬\n‫اآلن وأرفــض تســليمها حتــى يعطينــي كامــل اإليجــار وتكاليــف النقــل‬\n‫واألثــاث التــي خســرتها هــذه إجابتــي فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ولكــون املدعــي يطالــب بإرجــاع أجــرة الشــقة وإلقــراره أنــه‬\n‫ال زال يف الشــقة إلــى اآلن ولكــون املدعــى عليــه دفــع بعــدم حتمــل‬\n‫املؤجــر تكاليــف نقــل األثــاث وتركيبــه وللقاعــدة الفقهيــة املعــروف‬\n‫عرفــا كاملشــروط شــرطا وملــا ذكــره أهــل العلــم باســتحقاق األجــرة‬\n‫مبضــي املــدة كمــا قــال العالمــة منصــور البهوتــي يف كشــاف القنــاع‬\n‫(‪( )145/9‬وتســتقر األجــرة مبضــي املــدة حيــث ســلمت لــه إليــه العــن‬\n\n\n                                                                                    ‫‪228‬‬\n\f      ‫التــي وقعــت اإلجــارة عليهــا وال حاجــز لــه عــن االنتفــاع ولــو لــم ينتفــع)‪.‬‬\n      ‫لذلــك كلــه فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي وأخليــت‬\n      ‫ســبيل املدعــى عليــه مــن هــذه الدعــوى وبعرضــه علــى املدعــي لــم يقنــع‬\n      ‫بــه وبعرضــه علــى املدعــى عليــه قــرر القناعــة وأفهمــت املدعــى عليــه بــأن‬\n      ‫مــدة االعتــراض ثالثــون يومـ ًا تبــدأ تاريــخ ‪1434/2/18‬ه ـ يســقط بعدها‬\n      ‫حقــه يف االعتــراض ويكتســب احلكــم القطعيــة إن لــم يتقــدم بشــيء‬\n      ‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                     ‫وســلم ‪ .‬حــرر يف ‪1434/2/17‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n      ‫باملدينــة املنــورة فقــد وردت املعاملــة مــن محكمــة االســتئناف بقرارهــا‬\n      ‫رقم ‪ 34211085‬يف ‪1434/5/12‬هـ املرفق باملعاملة الصادر من الدائرة‬\n      ‫األولــى املتضمــن املوافقــة علــى احلكــم ‪ ..‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ -‬وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى احلكــم الصــادر‬\n      ‫مــن فضيلــة الشــيخ (‪ )....‬القاضــي باحملكمــة العامــة باملدينــة املنــورة‬\n      ‫واملســجل بعــدد ‪ 3440021‬وتاريــخ ‪1434/2/18‬هـ ـ واملتضمــن دعــوى‬\n               ‫(‪ )....‬ضــد (‪ )....‬يف مبلــغ مالــي واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n      ‫علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                         ‫وصحبــه وســلم‪.‬‬\n\n\n\n‫‪229‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":226,"source_page_end":229,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7f15fbafea3c38c6a4be42af62a5ea97e52f7c0d50421dc13a394e1d7bc4c03e","normalized_text_hash":"225de0ce6e3766c6d46ee6fa38ce347dfa6ae10cb74be8fc5e22a1c19b45f487","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p226-3440021"},{"id":"089ea602-a3d3-5275-bf61-bb76f1dcbb46","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة أب بأجرة شقة له أسكن فيها ابنته املتزوجة -إنكار الزوج االستحقاق خلروج الزوجة من املنزل املخصص لها -عدم وجود عقد بينهما -صرف النظر عن طلب املدعي.","document_number":"34233633","case_number":"3421714","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"إجارة -مطالبة أب بأجرة شقة له أسكن فيها ابنته املتزوجة -إنكار الزوج االستحقاق خلروج الزوجة من املنزل املخصص لها -عدم وجود عقد بينهما -صرف النظر عن طلب املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/7:‬هـ   ‬\n                   ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪34233633 :‬‬\n                      ‫َر ْق ُم الدعوى‪3421714 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 34298395‬تاريخه‪1434/8/16 :‬هـ‬\n\n\n‫إجــارة ‪ -‬مطالبــة أب بأجــرة شــقة لــه أســكن فيهــا ابنتــه املتزوجــة ‪-‬إنــكار‬\n‫الــزوج االســتحقاق خلــروج الزوجــة مــن املنــزل املخصــص لهــا ‪ -‬عــدم‬\n                  ‫وجــود عقــد بينهمــا ‪ -‬صــرف النظــر عــن طلــب املدعــي‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                            ‫تســبيب احلكــم‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه أنــه قــام ببنــاء شــقه البنتــه‬\n‫واوالدهــا بســبب خــروج ابنتــه مــن بيــت الزوجيــة خلــاف دار بينهــا وبــن‬\n‫املدعــى عليــه زوجهــا ولقــد ســكنت فيــه وقــام املدعــى بتقديــر أجــرة‬\n‫الشــقة بألــف ريــال شــهريا ويطلــب إلــزام املدعــى عليــه بدفعهــا لــه ‪ -‬أقــر‬\n‫املدعــى عليــه بأنــه زوج ابنتــه وحصــول اخلــاف وذهابهــا ملنــزل املدعــي‬\n‫والدهــا إال أنــه دفــع بأنــه لــم يســتأجر الشــقة منــه بــل يطالــب ابنتــه‬\n‫بالعــودة ملنزلــه ‪ -‬جــرى ســؤال املدعــي هــل قــام املدعــى عليــه بإبــرام عقــد‬\n‫أجــرة معــه أو طلــب منــه ذلــك فأجــاب املدعــي بالنفــي ‪ -‬عليــه وإلقــرار‬\n‫املدعــى عليــه بخــروج زوجتــه مــن منزلهــا بإختيارهــا وإنــكاره إســتئجار‬\n‫الشــقة وألن املدعــي قــام بإســكان ابنتــه إحســانا منــه لهــا كمــا أن بنــت‬\n                                                                                       ‫‪230‬‬\n\f      ‫املدعــي زوجــة املدعــى عليــه ليــس لهــا ســكن خلروجهــا مــن بيــت زوجهــا‬\n      ‫ولهــا املطالبــة بالنفقــة باحملكمــة املختصــة بذلــك ولــكل مــا تقــدم فقــد‬\n      ‫صرفــت الدائــرة النظــر عــن مطالبــة املدعــي وأخليــت ســبيل املدعــى‬\n      ‫عليــه ‪ -‬قــرر املدعــي عــدم القناعــة مت افهامــه بتعليمــات االعتــراض ‪-‬‬\n                                      ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪    .......‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة مبحافظــة جــدة   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 3421714‬وتاريــخ‬\n      ‫‪ 1434/01/13‬هــ   املقيــدة باحملكمــة برقــم ‪ 34104249‬وتاريــخ‬\n      ‫‪ 1434/01/13‬هــ  ففــي يــوم  األحــد املوافــق‪ 1434/05/26‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪   00:10‬وفيهــا حضــر ‪ .........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ........‬وادعــى علــى احلاضــر معــه ‪ .......‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..........‬قائــا يف دعــواه عليــه‬\n      ‫تــزوج املدعــى عليــه ابنتــي وأجنــب منهــا ابنــن وحصــل خــاف بينهمــا‬\n      ‫وخرجــت مــن منزلــه وســكنت عنــدي وقمــت ببنــاء شــقه لهــا وألبنائهــا‬\n      ‫وأســكنتها هــي وابنيهــا بالشــقة مــن تاريــخ ‪1433/03/01‬ه ـ وقــدرة‬\n      ‫أجــرة الشــقة بألــف ريــال وطلبــت منــه ســداد مبلــغ أربعــة عشــر ألــف ريــال‬\n      ‫حتــى تاريــخ ‪1434/06/01‬ه ـ لــذا أطلــب إلزامــه بســداد مبلــغ أربعــة‬\n      ‫عشــر ألــف ريــال قيمــة اإليجــار الــذي بذمتــه هــذه دعــواي وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه اجــاب قائــا مــا ذكــره املدعــي مــن زواجــي بابنتــه‬\n      ‫وإجنابــي منهــا ابنــن وخروجهــا مــن بيتهــا وســكنها عنــده هــذا صحيــح‬\n‫‪231‬‬\n\f‫وامــا مــا ذكــره مــن اســتئجار الشــقة فهــذا غيــر صحيــح والصحيــح انــي‬\n‫لــم أســتأجر الشــقة وهــي مــن خرجــت وأقمــت عليهــا دعــوى لطلــب بيــت‬\n‫الطاعــة هــذه إجابتــي وبســؤال املدعــي عــن بينــة اســتئجار املدعــي للشــقة‬\n‫اجــاب قائــا ليــس لــدي بينــه وزوجتــه بالشــقة وولديهــا هــذه اجابتــي‬\n‫وبســؤاله هــل لديــه عقــد إيجــار وهــل طلــب منــك اســتئجار شــقة لهــا‬\n‫اجــاب قائــا ال وبســؤالهما هــل لديهمــا إضافــة علــى مــا ذكــر اجابــا‬\n‫قائلــن ليــس لدينــا إضافــة نكتفــي مبــا ذكرنــا هكــذا اجابــا فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واالجابــة وحيــث صــادق املدعــى عليــه علــى‬\n‫خــروج زوجتــه مــن منزلهــا باختيارهــا وانكــر اســتئجار الشــقة وال بينــة‬\n‫للمدعــي كمــا ان املدعــي قــام بإســكان ابنتــه إحســانا منــه لهــا كمــا‬\n‫ان بنــت املدعــي وزوجــة املدعــى عليــه ليــس لهــا الســكن خلروجهــا مــن‬\n‫بيــت زوجهــا ولهــا املطالبــة بالنفقــة باحملكمــة املختصــة بذلــك ولــكل‬\n‫مــا تقــدم فقــد صرفــت النظــر عــن دعــوى املدعــي وبعــرض احلكــم علــى‬\n‫املدعــي قــرر املعارضــة بالئحــة جــرى النطــق باحلكــم الســاعة العاشــرة‬\n‫والنصــف كمــا أفهــم املدعــي باملراجعــة خــال عشــرة أيــام الســتالم‬\n‫صــورة مــن احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف‪ 1434/5/26‬هـ ـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ‬\n‫فقــد جــرى م ّنــا نحــن قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة‬\n‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــا ُع علــى هــذا‬\n‫احلكــم الصــادر مــن فضيلــة الشــيخ ‪  ............ /‬القاضــي يف احملكمــة‬\n‫اجلزائية مبحافظة جدة املسجل بعدد ‪ 34233633‬وتاريخ ‪1434/6/7‬هـ‬\n‫املتضمــن دعــوى ‪ ........‬ضــد ‪  ......‬احملكــوم في ــه مبــا دون باطــن الصك ‪،‬‬\n\n\n                                                                                   ‫‪232‬‬\n\f      ‫وبدراســة احلكــم وص ــورة ضبط ــه والئحتــه االعتراضيــة  تقــرر املوافقــة‬\n      ‫علــى احلكــم بصــرف النظــر عــن الدعــوى  ‪ .‬وبــاهلل التوفيــق ‪  ،‬وصل ــى‬\n                               ‫اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪233‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":230,"source_page_end":233,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ea67fc1ed8f4265c1498eeaf7606281d21dbf7e5c7eb9c05933c629e33e70aaa","normalized_text_hash":"d9591d7bda50269db4a64925e52eebfaaf30c4240bcf87948f41d74f10fa098e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p230-34233633"},{"id":"33cc4c39-1102-5b5f-9147-32f4adca9bd2","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار -املسلمون على شروطهم -عدم االعتداد بالشروط امللحقة من طرف واحد -احلكم بإلزام املدعى عليه بإخاء العقار محل الدعوى وتسليمه للمدعي كما استلمه - صرف النظر عن طلب املدعي حساب أجرة على املدعى عليه عند تأخره أسبوع ا بعد انتهاء العقد لعدم موجبه -إفهام املدعي بأن له املطالبة بذلك عند وجود سببه .","document_number":"3435758","case_number":"33019594","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/12","year":"1434","subject":"إجارة -إخاء عقار -املسلمون على شروطهم -عدم االعتداد بالشروط امللحقة من طرف واحد -احلكم بإلزام املدعى عليه بإخاء العقار محل الدعوى وتسليمه للمدعي كما استلمه - صرف النظر عن طلب املدعي حساب أجرة على املدعى عليه عند تأخره أسبوع ا بعد انتهاء العقد لعدم موجبه -إفهام املدعي بأن له املطالبة بذلك عند وجود سببه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/12 :‬هـ  ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪3435758 :‬‬\n                    ‫َر ْق ُم الدعوى‪33019594 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n      ‫‪/34307647‬ق‪ 1/‬تاريخه‪1434/8/28 :‬هـ‬\n\n\n‫إجــارة ‪ -‬إخــاء عقــار ‪ -‬املســلمون علــى شــروطهم ‪ -‬عــدم االعتــداد‬\n‫بالشــروط امللحقــة مــن طــرف واحــد ‪ -‬احلكــم بإلــزام املدعــى عليــه‬\n‫بإخــاء العقــار محــل الدعــوى وتســليمه للمدعــي كمــا اســتلمه ‪-‬‬\n‫صــرف النظــر عــن طلــب املدعــي حســاب أجــرة علــى املدعــى عليــه عنــد‬\n‫تأخــره أســبوع ًا بعــد انتهــاء العقــد لعــدم موجبــه ‪ -‬إفهــام املدعــي بــأن لــه‬\n                                        ‫املطالبــة بذلــك عنــد وجــود ســببه ‪.‬‬\n\n\n\n\n                     ‫‪ -1‬قوله تعالى « يا أيها الذين آمنوا اوفوا بالعقود »‬\n                  ‫‪ -2‬قوله صلى اهلل علية وسلم «املسلمون على شروطهم»‬\n\n\n\n\n‫ال من‬‫ادعــى املدعــى وكالــة بــأن املدعــى عليه  أســتأجر مــن موكله مح ً‬\n‫عمارتــه يف حــي ‪ ...‬مبحافظــة ‪ ...‬بأجــرة ســنوية قدرهــا خمســة وعشــرون‬\n‫ألــف ريــال ملــدة ســنة وقــد قــام املدعــى عليــه بإضافــة مالحظــات علــى‬\n‫العقــد بــدون علــم املدعــى أصالــة مطالبــا  مبــدد تخالــف نــص العقــد‬\n‫ولــذا فــإن املدعــى أصالــة ال يرغــب يف جتديــد العقــد مــع املدعــى عليــه‬\n‫ويطلــب الكــم بإخــاء احملــل محــل الدعــوى وتســليمه كمــا اســتلمه‬\n‫عنــد نهايــة العقــد وفــى حالــة تخلفــه عــن تســليم احملــل بعــد أســبوع مــن‬\n                                                                                         ‫‪242‬‬\n\f        ‫تاريــخ نهايــة العقــد يحســب احملــل عليــه بأجــرة ســنوية قدرهــا أربعــون‬\n        ‫ألــف ريــال لفــروق األيــام حتــى التســليم‪ - .‬أجــاب املدعــى عليــه بــأن مــا‬\n        ‫ذكــره املدعــى وكالــة بعضــه صحيــح وبعضــه غيــر صحيــح والصحيــح‬\n        ‫انــه مت االتفــاق علــى اســتئجار محلــن متجاوريــن وليــس محــا واحــدا‬\n        ‫بأجــرة ســنوية قدرهــا أربعــون ألــف ريــال ملــدة ثــاث ســنوات وبعــد مــدة‬\n        ‫قــام املدعــى بانتــزاع احملــل الثانــي بــدون تعويــض ثــم ذهــب املدعــى‬\n        ‫وانشــأ عقــد ًا جديــد ًا لــدى املكتــب العقــاري بــدون حضــور املدعــى‬\n        ‫عليــه يتضمــن إيجــار محــل واحــد ملــدة ســنة وقــام بالتوقيــع علــى العقــد‬\n        ‫لوحــدة فقــام املدعــى عليــه واطلــع علــى العقــد وتبــن لــه انــه خــاف مــا‬\n        ‫مت االتفــاق عليــه فقــام بإضافــة مالحظــات علــى العقــد نصهــا مــدون يف‬\n        ‫نــص القضيــة  ‪ -‬قــرر املدعــى عليــه أن الــذي دفــع أجرتــه وحتــت يــده‬\n        ‫هــو محــل واحــد فقــط ‪ -‬اطلــع حاكــم القضيــة علــى عقــد التأجيــر بــن‬\n        ‫الطرفــن ‪ -‬جــري عــرض جــواب املدعــى عليــه علــى املدعــى وقــرر عــدم‬\n        ‫صحتــه ‪ -‬بنــاء علــى مــا ســلف فقــد قــرر حاكــم القضيــة انــه بنــاء علــى‬\n        ‫إقــرار املدعــى عليــه بتوقيعــه علــى العقــد وان مــا إضافــة مــن شــروط هــو‬\n        ‫مــن طرفــه فقــط كمــا اقــر بــأن الــذي دفــع أجرتــه وحتــت يــده هــو محــل‬\n      ‫واحــد فقــط  ولقولــه تعالــى ﴿ َيــا َأ ُّي َهــا الَّذِ يـ َـن آ ََم ُنــوا َأ ْو ُفــوا ِبا ْل ُع ُقــو ِد (‪  ﴾ )1‬‬\n        ‫لذلــك فقــد الــزم ناظــر القضيــة املدعــى عليــه بــأن يخلــى محــل الدعــوى‬\n        ‫وتســليمه للمدعــى أصالــة بنهايــة العقــد علــى حالتــه التــي اســتلمها‬\n        ‫وصــرف النظــر عــن طلــب املدعــى حســاب أجــرة علــى املدعــى عليــه‬\n        ‫عــن تأخــره بعــد انتهــاء العقــد لعــدم موجبــه وان للمدعــى احلــق باملطالبــة‬\n        ‫بذلــك عنــد وجــود ســببه ‪ -‬قــرر الطرفــان عــدم القناعــة ‪ -‬صــدر قــرار‬\n             ‫محكمــة االســتئناف باملنطقــة الشــرقية باملصادقــة علــى احلكــم ‪.‬‬\n\n\n‫‪243‬‬\n\f‫العامة مبحافظة‬\n          ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة‬\n‫القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة القطيــف برقــم ‪ 33519594‬وتاريــخ ‪1433/08/12‬ه ـ‬        ‫َ‬\n‫يف يــوم الثالثــاء املوافق‪1433/10/17‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم حــال وكالتــه عــن‬\n‫ســعودي  اجلنســية مبوجــب الســجل املدنــي رقــم    مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل اخلبــر برقــم ‪ 33203482‬يف ‪1433/7/30‬ه ـ‬\n‫والتــي تتضمــن املرافعــة واملدافعــة وســماع الدعــاوي والــرد عليهــا‬\n‫واإلقــرار واإلنــكار والصلــح والتنــازل وطلــب اليمــن ورده واالمتنــاع‬\n‫عنــه وإحضــار الشــهود والبينــات والطعــن فيها واإلجابــة واجلرح والتعديل‬\n‫والطعــن بالتزويــر وطلــب تطبيــق املــادة ‪ 230‬مــن نظــام املرافعــات‬\n‫الشــرعية واملطالبــة بتنفيــذ األحــكام وقبــول االحــكام ونفيهــا‬\n‫واالعتــراض علــى األحــكام وطلــب االســتئناف وإنهــاء مــا يلــزم وحضــور‬\n‫اجللســات يف جميــع الدعــاوي لــدى احملاكــم ) أ ‪ .‬ه ـ وحضــر حلضــوره‬\n‫ا ‪ :‬لقــد‬ ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى األول قائـ ً‬\n‫قــام موكلــي بتأجيــر املدعــى عليــه محــل يف عمــارة تعــود ملكيتهــا لــه‬\n‫واقعــة يف حــي ‪ ...‬مبحافظــة اخلبــر وذلــك بأجــرة ســنوية قدرهــا خمســة‬\n‫وعشــرون ألــف ريــال تدفــع يف يدايــة العقــد وكان العقــد يبــدأ يف‬\n‫‪2012/1/1‬م وينتهــي يف ‪2013/1/1‬م وحيــث أن املدعــى عليــه قــام‬\n‫بإضافــة مالحظــات علــى العقــد دون علــم موكلــي مطالبـ ًا مبــدد مبالــغ‬\n‫تخالــف نصــوص العقــد لذلــك ال يرغــب موكلــي يف جتديــد العقــد‬\n\n                                                                                  ‫‪244‬‬\n\f      ‫للمدعــى عليــه ويطلــب احلكــم علــى املدعــى عليــه بإخــاء احملــل محــل‬\n      ‫الدعــوى بعــد عمــل الصيانــة الالزمــة وهــي اصــاح اجلــدران ودهنهــا‬\n      ‫وإزالــة مخلفــات الديــزل وإفــراغ احملــل مــن جميــع مــا يخصــه وذلــك عنــد‬\n      ‫نهايــة العقــد املتفــق عليــه وهــو تاريــخ ‪2013/1/1‬م ويف حالــة تخلفــه عــن‬\n      ‫تســليم احملــل بعــد أســبوع مــن تاريــخ إنتهــاء العقــد يحســب عليــه احملــل‬\n      ‫بأجــرة ســنوية قدرهــا أربعــون ألــف ريــال لفــروق األيــام حتــى التســليم‬\n      ‫ا ‪ :‬ماذكــره‬   ‫هــذه دعــواي ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫املدعــي وكالــة يف دعــواه بعضــه صحيح وبعضه غيــر صحيح والصحيح‬\n      ‫هــو أنــه مت األتفــاق مــع املدعــي أصالــة علــى اســتئجار محلــن متجاوريــن‬\n      ‫ا واحــد ًا بأجــرة قدرهــا أربعــون ألــف ريــال علــى أن يكــون‬     ‫وليــس مح ـ ً‬\n      ‫مــدة اإليجــار ثــاث ســنوات ويكــون أحــد احمللــن مغســلة مالبــس‬\n      ‫واآلخــر صالــون حالقــة رجالــي ومت ترتيــب احمللــن لذلــك وبعــد االنتهــاء‬\n      ‫مــن الصيانــة للمحلــن قــام املدعــي أصالــة بانتــزاع احملــل الثانــي املعــد‬\n      ‫للحالقــة بــدون التعويــض عليــه بحجــة الشــبهة يف العمــل ‪ .‬ثــم ذهــب‬\n      ‫املدعــي أصالــة بإنشــاء عقــد يف مكتــب عقــاري بــدون حضــوري يتضمن‬\n      ‫إيجــار محــل واحــد فقــط وملــدة ســنة واحــدة فقــط وقــام بالتوقيــع علــى‬\n      ‫العقــد بــدون توقيعــي وبــدون علمــي ثــم بعــد ذلــك حضــرت للمكتــب‬\n      ‫العقــاري وأطلعــت علــى العقــد وتبــن لــي أنــه خــاف مــا مت االتفــاق عليــه‬\n      ‫بينــي وبــن املدعــي أصالــة فقمــت بإضافــة مالحظــة علــى العقــد وهــذا‬\n      ‫نصهــا ( مت صــرف مبلــغ وقــدره ‪ 40274‬ريــال أربعــون ألــف ومائتــان‬\n      ‫وأربعــة وســبعون ريــال وذلــك لتقســيم محــات العمــارة املســتأجرة بهــا‬\n      ‫وكذلــك لتجميــل املغســلة ‪ 1‬ـ يتــم إرجــاع املبلــغ بواســطة املؤجــر الــذي مت‬\n      ‫صرفــه  علــى تقســيم احملــات والــذي يبلــغ ‪ 22164‬ريــال أثنــان وعشــرون‬\n\n\n‫‪245‬‬\n\f‫ألــف ومائــة وأربعــة وســتون  عنــد عــدم جتديــد العقــد ‪ 2‬ـ ال يتــم إرجــاع‬\n‫املبلــغ الــذي مت صرفــه علــى جتميــل احملــل و هــو ‪18110‬ريــال ثمانيــة‬\n‫عشــر ألــف ومائــة وعشــرة ريــال عنــد عــدم جتديــد العقــد ‪ ) .‬أ‪ .‬ه ـ وأنــا‬\n‫موافــق علــى طلــب املدعــي وكالــة إخــاء احملــل يف مقابــل أن يتــم‬\n‫تعويضــي خللــو القــدم الــذي دفعتــه للمســتأجر القــدمي حيــث إنــي قــد‬\n‫اشــتريت احمللــن مــن املســتأجر الســابق قبــل هــذا العقــد وقــدره ثمانيــة‬\n‫وثالثــن ألــف ريــال وكذلــك تعويضــي عــن أعمــال الصيانــة التــي عملتها‬\n‫للمحــل الــذي مت انتزاعــه منــي وقدرهــا اثنــان وعشــرون ألــف ومائــة‬\n‫وأربعــة وســتون ريــال هــذه إجابتــي ثــم طلبــت مــن الطرفــن عقــد اإليجــار‬\n‫فأحضــره املدعــى عليــه وبعــد االطــاع عليــه وجــد أنه صــادر من مكتب‬\n‫‪ ...‬للعقــارات برقــم ‪ 182‬يف ‪1433/2/27‬ه ـ املوافق ‪2012/2/27‬م وهذا‬\n‫نصــه ( عقــد إيجــار التاريــخ ‪1433/2/27‬ه ـ املوافــق ‪2012/2/27‬م نــوع‬\n‫العقــار محــل جتــاري موقعــه ورقمــه ‪ ....‬شــارع ‪ ...‬مقابــل ‪ ...‬الغــرض مــن‬\n‫اســتعماله مغســلة مالبــس مــدة إيجــار ســنة فقــط بــدء اإليجــار‬\n‫‪2012/1/1‬م نهايــة اإليجــار ‪2013/1/1‬م مبلــغ اإليجــار ‪ 25000‬خمســة‬\n‫وعشــرون ألــف ريــال طريقــة الدفــع ســنوي حوالــة علــى احلســاب أســم‬\n‫املؤجــر رقــم البطاقــة ـ ‪...‬ه ـ عنوانــه ‪ ...‬رقــم الهاتــف‪ ...‬اســم املســتأجر‪...‬‬\n‫رقــم البطاقــة ‪ ...‬ـ ‪...‬ه ـ عنوانــه ‪ ....‬تفاصيــل ‪ /‬ومالحظــات ‪ 1000 :‬تأمــن‬\n‫و‪ 700‬ريــال مصاريــف ميــاه ســنوي ـ التجديــد ســنوي ًا ‪ .‬الشــروط التــي مت‬\n‫االتفــاق عليهــا ‪1‬ـ ثمــن اســتهالك الكهربــاء واملــاء والتلفــون والغــاز علــى‬\n‫املســتأجر ‪ ،‬كمــا عليــه دفــع تأمــن الكهربــاء وأيــة رســوم أو ضرائــب‬\n‫علــى العقــار وليــس للمؤجــر عالقــة بهــا ‪ 3‬ـ ليــس للمســتأجر احلــق يف‬\n‫مطالبــة املؤجــر بقيمــة التحســينات واإلصالحــات التــي أدخلهــا علــى‬\n\n\n                                                                                       ‫‪246‬‬\n\f      ‫العقــار ‪ 3‬ـ ـ علــى املســتأجر أن يســلم العقــار عنــد خروجــه منــه كمــا‬\n      ‫إســتلمه عنــد بدايــة اإليجــار وعلبــه أن يقــوم بإصــاح مــا أتلفــه أو أحدثــه‬\n      ‫مــن خــراب بالعقــار املذكــور ‪ .‬ويكــون مســؤ ًال عــن كل ضــرر فيــه‬\n      ‫ويجــب عليــه اإلصــاح والصيانــة علــى حســابه اخلــاص مبــا يف ذلــك‬\n      ‫الزجــاج واألدوات الصحيــة واألقفــال وغيرهــا ‪ 4 .‬ـ ـ ال يحــق للمســتأجر‬\n      ‫تغييــر أي شــيء يف القعــار أو تأجيــره كلــه أو قســم ًا منــه إال بعــد موافقــة‬\n      ‫املؤجــر كتابيـ ًا ‪5 .‬ـ ـ طيلــة مــدة اإليجــار تكــون أعمــال الصيانــة الالزمــة‬\n      ‫للعقــار بســبب اإلســتعمال علــى املســتأجر وال يحــق لــه مطالبــة املؤجــر‬\n      ‫فيهــا ‪ 6 .‬ـ للمؤجــر احلــق يف تكليــف املســتأجر بإخــاء العقــار وإلغــاء‬\n      ‫العقــد إذا حصــل منــه تأخيــر عــن دفــع اإليجــار يف ميعــاده ويف حالــة عــدم‬\n      ‫محافطتــه علــى نظافــة وســامة العقــار ‪ 7 .‬ـ ـ يدفــع اإليجــار مبوجــب‬\n      ‫ســندات رســمية مــن املؤجــر وكل دفعــه ال يؤخــذ فيهــا وصــل كمــا‬\n      ‫ذكــر ال تعتبــر ‪ 8 .‬ـ ـ يف حالــة غيــاب املســتأجر عــن الســداد أكثــر مــن‬\n      ‫شــهرين ولــم يعــرف الســبب فاملالــك يتصــرف ويخبــر الســلطات احملليــة‬\n      ‫بطلــب إخــاء محلــة ويســلم األثــاث للحكومة وللمؤجــر احلق يف حتصيل‬\n      ‫اإليجــار مــن قيمــة األثــاث ‪ 9 .‬ــ  يدفــع املســتأجر تأمــن مبلــغ ‪ /‬وعنــد‬\n      ‫إخــاء احملــل يــرد التأمــن لــه بعــد إخــاء طــرف تســديد الكهربــاء‬\n      ‫وامليــاه ‪ 10‬ـ ـ مــدة هــذا العقــد ســنة تبــدأ بتاريــخ ‪2012/1/1‬م وتنتهــي‬\n      ‫بتاريــخ ‪2013/1/1‬م ويجــدد هــذا العقــد بهــذه الشــروط أو غيرهــا إذا‬\n      ‫رغــب الطــرف األول ‪ ،‬أمــا يف حالــة عــدم رغبتــه فيعتبــر حــق املســتأجر‬\n      ‫منتهي ـ ًا ويجــب عليــه إخــاء املأجــور‪ 11 .‬يشــعر كل مــن الطرفــن‬\n      ‫أحدهمــا اآلخــر برغبتــه يف اإلســتمرار باإليجــار أو عدمــه قبــل إنتهــاء‬\n      ‫املــدة املشــار إليهــا بشــهر واحــد علــى األقــل ويف حالــة عــدم إشــعار‬\n\n\n‫‪247‬‬\n\f  ‫أحدهمــا اآلخــر يعتبــر ممــددا تلقائيـ ًا بنفــس الشــروط ‪ 12‬ـ ال قيمــة ألي‬\n  ‫مبلــغ يدعــي الطــرف الثانــي دفعــه مالــم يحمــل إيصــا ًال موقع ـ ًا مــن‬\n  ‫الطــرف األول   ‪ 13‬ـ ـ يقــر الطرفــان املتعاقــدان أنهمــا قــرأ اإلتفــاق‬\n  ‫ويلتزمــان بتنفيــذ بنــوده ويحتفــظ كل منهمــا بنســخة مــن هــذا العقــد‬\n  ‫للرجــوع إليــه عنــد الطلــب ‪ 14‬يعتبــر هــذا العقــد ســاري املفعــول إعتبــار ًا‬\n  ‫مــن يــوم ‪2012/1/1‬م مالحظــة (يحــق للمؤجــر أن يطلــع علــى حالــة‬\n  ‫املأجــور بــن احلــن واآلخــر لضمــان ســامته)‪ .‬شــروط إضافيــة ‪ :‬إذا‬\n  ‫تأخــر املســتأجر عــن دفــع اإليجــار املقــدم يعتبــر هــذا العقــد الغيـ ًا ويحــق‬\n  ‫للمؤجــر التصــرف يف ملكــه دون إعتــراض مــن املســتأجر ‪ .‬مت اإلتفــاق‬\n  ‫بــن الطرفــن وبيــد كل منهمــا نســخة مــن هــذا العقــد وبعــد اإلتــكال‬\n  ‫علــى اهلل جــرى التوقيــع واملكتــب غيــر مســؤول عــن أي خــاف بــن‬\n  ‫الطرفــن ‪ .‬املؤجــر توقيعــه املســتأجر توقيعــه ختــم املكتــب والتوقيــع‬\n  ‫كمــا يوجــد يف العقــد مالحظــة جانبيــة مكتوبــة بخــط اليــد ونصهــا‬\n  ‫‪:‬مت صــرف مبلــغ وقــدره ‪ 40274‬ريــال أربعــون ألــف ومائتــان وأربعــة‬\n  ‫وســبعون ريــال وذلــك لتقســيم محــات العمــارة املســتأجرة بهــا وكذلــك‬\n‫لتجميــل املغســلة ‪ 1‬ـ يتــم إرجــاع املبلــغ بواســطة املؤجــر الــذي مت صرفــه  ‬\n  ‫علــى تقســيم احملــات والــذي يبلــغ ‪ 22164‬ريــال أثنــان وعشــرون ألــف‬\n  ‫ومائــة وأربعــة وســتون  عنــد عــدم جتديــد العقــد ‪ 2‬ـ ال يتــم إرجــاع املبلــغ‬\n  ‫الــذي مت صرفــه علــى جتميــل احملــل و هــو ‪18110‬ريــال ثمانيــة عشــر‬\n  ‫ألــف ومائــة وعشــرة ريــال عنــد عــدم جتديــد العقــد ) أ‪ .‬ه ـ هــذا ونظــر ًا‬\n  ‫النتهــاء وقــت اجللســة وحضــور وقــت الصــاة رفعــت اجللســة ويف جلســة‬\n‫أخــرى حضــر املدعــي أصالــة واملدعــي وكالــة ولــم يحضــر املدعــى عليــه  ‬\n  ‫وال مــن ينــوب عنــه ولــم يتقــدم بــأي عــذر وبعــرض جــواب املدعــى عليــه‬\n\n\n                                                                                          ‫‪248‬‬\n\f      ‫ا مــا ذكــره املدعــى عليــه يف جوابــه‬      ‫علــى املدعــي وكالــة أجــاب قائ ـ ً‬\n      ‫ا وأريــد أن أوضــح مــا يلــي‪ )1 :‬العقــد‬   ‫كلــه غيــر صحيــح جملــة وتفصيـ ً‬\n      ‫ينــص يف البنــد الرابــع منــه علــى أنــه ال يحــق للمســتأجر تغييــر أي شــيء‬\n      ‫يف العقــار أو تأجيــره كلــه أو قســم منــه إال بعــد موافقــة املؤجــر كتابيـ ًا‬\n      ‫ولــم يحصــل أن متــت كتابــة أي شــيء ‪  )2 .‬أن املدعــى عليــه قــد وكل‬\n      ‫صاحــب املكتــب العقــاري وهــو وكالــة شــرعية تخولــه حــق التوقيــع‬\n      ‫واالســتالم والتســليم ووكيلــه هــو مــن وقــع علــى عقــد اإليجــار ثــم ســلم‬\n      ‫املدعــي وكالــة صــورة مــن صــك الوكالــة املشــار إليهــا ثــم قــررت رفــع‬\n      ‫اجللســة مــن أجــل االطــاع علــى صــك الوكالــة وحضــور املدعــى عليــه‬\n      ‫ويف جلســة أخــرى حضــر املدعــي أصالــة واملدعــي وكالــة وحضــر‬\n      ‫حلضورهمــا املدعــى عليــه   هــذا وقــد ســبق أن أحضــر املدعــى صــك‬\n      ‫العقــار محــل الدعــوى وباالطــاع عليــه وجــد أنــه صــادر مــن كاتــب‬\n      ‫عــدل اخلبــر بقــم ‪ 119‬يف ‪1422/11/6‬ه ـ ويتضمــن متلــك للعقــار الواقــع‬\n      ‫يف ‪ ...‬باخلبــر وحــدوده وأطوالــه  كمــا يلــي‪ :‬شــما ًال ‪ :‬بطــول ثمانيــة عشــر‬\n      ‫متــر ًا ويحدهــا القطعــة رقــم ‪ . 12‬وجنوب ـاً‪ :‬بطــول ثمانيــة عشــر متــر ًا‬\n      ‫ويحدهــا شــارع عــرض ‪ 25‬متــر ًا ‪ .‬وشــرق ًا ‪ :‬بطــول خمســة وعشــرون متــر ًا‬\n      ‫ويحدهــا القطعــة رقــم ‪ 9‬وغربـ ًا ‪ :‬بطــول خمســة وعشــرون متــر ًا ويحدهــا‬\n      ‫القطعــة رقــم ‪ 13‬واملســاحة األجماليــة ‪ :‬أربعمائــة وخمســن متــر ًا مربعـ ًا‬\n      ‫‪450‬م‪ ) 2‬أ ‪ .‬هـ  ‪ .‬كما مت االستفســار عن ســريان مفعول الصك  ســابق ًا‬\n      ‫فلــم يردنــا اجلــواب حتــى هــذه اجللســة  ثــم ســألت املدعــى عليــه عــن احملــل‬\n      ‫الــذي يعمــل فيــه حالي ـ ًا وعــن أجرتــه فقــال الــذي أعمــل فيــه حالي ـ ًا هــو‬\n      ‫محــل واحــد فقــط فيــه مغســلة مالبــس وأجرتــه خمســة وعشــرون ألــف‬\n      ‫ريــال ســلمتها للمدعــي أصالــة وأمــا احملــل الثانــي فليــس حتــت يــدي ولــم‬\n\n\n‫‪249‬‬\n\f‫أدفــع أجرتــه ‪ .‬هكــذا أجــاب ‪ .‬ثــم ســألته عــن توقيعــه علــى العقــد املتفــق‬\n‫عليــه بينهمــا واملرصــود نصــه ســابق ًا فقــال ‪ :‬نعــم أنــا الــذي وقعــت علــى‬\n‫العقــد ولكــن وضعــت شــروطي عليــه ‪ .‬هكــذا أجــاب ‪ .‬فســألته هــل‬\n‫كانــت هــذه الشــروط بعلــم املدعــي أصالــة ومبوافقتــه فقــال ‪ :‬ال ‪ .‬ثــم‬\n‫رفعــت اجللســة حتــى ورود جــواب االستفســار  ويف جلســة أخــرى حضــر‬\n‫املدعــي أصالــة واملدعــي وكالــة وحضــر حلضورهمــا املدعــى عليــه هــذا‬\n‫وقــد ســبق الكتابــة لكتابــة عــدل اخلبــر لإلفــاده عــن ســريان مفعــول‬\n‫الصــك وقــد وردتنــا االجابــة برقــم ‪ 3438379‬يف ‪1434/1/6‬ه ـ‬\n‫واملتضمنــة نفيــد كــم بــأن الصــك مرهــون لصالــح صنــدوق التنميــة‬\n‫العقاريــة وصــدر لــه صــك رهــن برقــم ‪ ....‬يف ‪1433/11/24‬ه ـ ‪ .‬أ‪.‬ه ـ ‪.‬ثــم‬\n‫ســألت الطرفــن عــن مســاحة املعــرض محــل الدعــوى وموقعــه مــن‬\n‫العمــارة فقــاال مســاحته ســتة وثالثــون متــر ًا مربع ـاً  ويقــع يف الــدور‬\n‫ـاء علــى مــا تقــدم مــن‬   ‫األرضــي يف اجلــزء الشــرقي مــن العمــارة ‪ .‬فبنـ ً‬\n‫الدعــوى واإلجابــة وإقــرار املدعــى عليــه بتوقيعــه علــى العقــد املرصــود‬\n‫مضمونــه ســابق ًا وأن مــا أضافــه مــن الشــروط هــو مــن طرفــه فقــط ولــم‬\n‫يكــن باتفــاق الطرفــن كمــا أنــه أقــر بــأن الــذي دفــع أجرتــه وحتــت يده‬\n‫هــو محــل واحــد وهــذا يؤيــد مــا جــاء يف العقــد واســتناد ًا إلــى قولــه تعالــى‬\n‫‪ ( :‬يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود) وقولــه صلــى اهلل عليــه وســلم ‪« :‬‬\n‫املســلمون علــى شــروطهم « لذلــك كلــه فقــد ألزمــت املدعــى عليــه‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم بــأن يخلــي املعــرض‬\n‫املســتأجر محــل الدعــوى ويســلمه للمدعــي أصالــة وذلــك بتاريــخ‬\n‫‪2013/1/1‬م علــى حالتــه التــي اســتلمه عليهــا وصرفــت النظــر عــن طلب‬\n‫املدعــي حســاب أجــرة علــى املدعــى عليــه عنــد تأخــره أســبوع بعــد انتهــاء‬\n\n\n                                                                                          ‫‪250‬‬\n\f      ‫العقــد لعــدم موجبــه وأفهمتــه بــأن لــه احلــق يف مطالبــة املدعــى عليــه‬\n      ‫بذلــك عنــد وجــود ســببه وبــه حكمــت وبعــرض احلكــم قــررا عــدم‬\n      ‫القناعــة وطلبــا رفعــه حملكمــة االســتئناف واســتعدا بتقــدمي الئحــة‬\n      ‫اعتراضيــة فأفهمــا مبراجعــة احملكمــة الســتالم نســخة احلكــم بعــد‬\n      ‫عشــرة أيــام وأن لــكل منهمــا ثالثــن يوم ـ ًا لالعتــراض وان لــم يتقدمــا‬\n      ‫خاللهــا بالالئحــة فيكتســب احلكــم القطعيــة ويســقط حقهمــا يف‬\n      ‫االســتئناف ففهمــا ذلــك ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمد‬\n                                                          ‫وعلى آله وصحبه وسلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد يف يــوم االثنــن املوافــق ‪1434/9/14‬ه ـ فتحــت‬\n      ‫ـاء علــى ورود املعاملــة مــن محكمــة االســتئناف باملنطقــة‬     ‫اجللســة بنـ ً‬\n      ‫الشــرقية مبوجــب كتــاب ســماحة رئيســها رقــم ‪ 341597964‬يف‬\n      ‫‪1434/9/6‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائرة احلقوقية‬\n      ‫األولــى رقــم ‪/34307647‬ق‪ 1/‬يف ‪1434/8/28‬ه ـ املتضمــن نــص‬\n      ‫احلاجــة منــه‪{  :‬بدراســة الصــك  وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم بعــد االجــراء األخيــر ‪،‬‬\n      ‫واهلل املوفــق قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه رئيــس الدائــرة  ختمــه وتوقيعه}‪.‬أهــ‪  .‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم  حــرر يف ‪1434/9/14‬ه ـ ‪،،‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى يف‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبحافظة القطيف برقــم ‪341487743‬‬\n      ‫وتاريــخ ‪1434/6/26‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪341597964‬‬\n\n\n‫‪251‬‬\n\f‫وتاريــخ ‪1434/7/2‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ /‬املســجل برقــم  وتاريــخ ‪1434/2/12‬ه ـ اخلــاص‬\n‫بدعــوى‪ /‬ضــد‪ /‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء‬\n      ‫األخيــر ‪ ،‬ولبيانــه حــرر يف ‪1434/8/28‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                  ‫‪252‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":242,"source_page_end":252,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ed61d2cf7d8db7488cefa9b7fde7a919806703cf3307283529c96fddbfa3b02e","normalized_text_hash":"ad3ee9859305ce310c4381507340e3c324d6c8d60c113d84b73adb8669ff0266","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p242-3435758"},{"id":"7c56a935-0b56-54f0-bc11-cde31c951ded","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -عقد استثمار -مطالبة املستأجر بأجرة عني -إدخال املالك يف املنازعة -املطالبة باألجرة فرع عن استمرار عقد االستثمار - انقضاء عقد االستثمار لنهاية مدته -احلكم برد الدعوى وصرف النظر النعدام صفة املدعي .","document_number":"34293038","case_number":"3435895","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/9","year":"1434","subject":"إجارة -عقد استثمار -مطالبة املستأجر بأجرة عني -إدخال املالك يف املنازعة -املطالبة باألجرة فرع عن استمرار عقد االستثمار - انقضاء عقد االستثمار لنهاية مدته -احلكم برد الدعوى وصرف النظر النعدام صفة املدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/9:‬هـ   ‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪34293038 :‬‬\n                            ‫َر ْق ُم الدعوى‪3435895 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34387491‬تاريخه‪1434/12/25 :‬هـ‬\n\n\n      ‫إجارة ‪ -‬عقد اســتثمار ‪ -‬مطالبة املســتأجر بأجرة عني ‪ -‬إدخال املالك‬\n      ‫يف املنازعــة ‪ -‬املطالبــة باألجــرة فــرع عــن اســتمرار عقــد االســتثمار ‪-‬‬\n      ‫انقضــاء عقــد االســتثمار لنهايــة مدتــه ‪ -‬احلكــم بــرد الدعــوى وصــرف‬\n                                                ‫النظــر النعــدام صفــة املدعــي ‪.‬‬\n\n\n\n\n                             ‫‪ -1‬قوله تعالى «يا أيها الذين آمنوا اوفوا بالعقود»‬\n                         ‫‪ -2‬قوله صلى اهلل علية وسلم «املسلمون على شروطهم»‬\n\n\n\n\n      ‫ادعــت املدعيــه بــأن املدعــى عليــه اســتأجر موقعـ ًا مبحطــة الوقــود لوضــع‬\n      ‫جهــاز صــراف آلــي ســيار ملــدة خمــس ســنوات بأجــرة معلومــه دون الوفــاء‬\n      ‫باالجــره ذكــرت املدعيــة أنهــا مســتثمرة محطــة الوقــود مــن مالكهــا‬\n      ‫ملــدة ثــاث ســنوات تبــدا يف ‪1426/5/1‬ه ـ وتطلــب املدعيــة إلــزام‬\n      ‫املصــرف بدفــع املبلــغ املســتحق ‪ -‬أقــر وكيــل املصــرف بدعــوى املدعيــة‬\n      ‫جملــة وتفصيــا إال أنــه دفــع بــأن االمتنــاع كان بنــاء علــى طلــب مالــك‬\n      ‫احملطــة التوقــف عــن دفــع األجــرة للمدعيــة لوجــود خــاف بينهمــا وطلــب‬\n      ‫وكيــل املصــرف إدخــال املالــك طرفــا يف القضيــة وال مانــع لــدى موكلــه‬\n\n‫‪253‬‬\n\f‫مــن دفــع األجــرة ملســتحقها ‪ -‬حضــر وكيــل املالــك وقــرر بــأن موكلــه‬\n‫لــم يجــدد معهــا العقــد وإمنــا وافــق علــى امهالهــا ســنة واحــدة فقــط مــن‬\n‫انتهــاء العقــد أي يجــب عليهــا إخــاء احملطــة يف‪1432/4/30‬ه ـ ‪ -‬أقــرت‬\n‫املدعيــة بــأن املالــك لــم يجــدد لهــا العقد بعد‪1432/4/30‬ه ـ ‪ -‬عليه وألن‬\n‫مطالبــة املدعيــة جتــاه املدعــى عليــه اعتبــارا مــن تاريــخ ‪2011/6/1‬م‬\n‫حتــى ‪2012/5/30‬م عليــه وبنــاء علــى مــدة عقــد االســتثمار بــن املدعيــة‬\n‫واملالــك ثــاث ســنوات ابتــداء مــن ‪1426/5/1‬ه ـ وحتــى ‪1429/5/1‬هــ‪،‬‬\n‫وبنــاء علــى إقــرار املدعيــة بــأن هــذا العقــد يتجــدد تلقائيــا بعــد موافقــة‬\n‫املالــك وإال يعتبــر ملغيــا ‪ ،‬وبنــاء علــى إقــرار املتداخــل وكالــة بتجديــد‬\n‫موكلــه للعقــد حتــى تاريخ‪1430/4/30‬هــ‪ ،‬عليــه وبنــاء علــى محضــر‬\n‫اتفاقيــة صلــح املــؤرخ يف ‪1431/6/29‬ه ـ احملــرر بــن املالــك واملدعيــة‬\n‫واملتضمــن اســتمرار العقــد بينهمــا حتــى تاريــخ ‪1432/4/30‬ه ـ ‪ ،‬وبنــاء‬\n‫علــى إقــرار املدعيــة جوابــا علــى مــا قــرره املتداخــل وكالــة مــن عــدم‬\n‫جتديــد عقــد االســتثمار بعــد تاريــخ ‪1432/4/30‬ه ـ ‪ ،‬عليــه وبنــاء علــى‬\n‫أن بدايــة تاريــخ مطالبــة املدعيــة للمدعــى عليــه يوافــق ‪1432/6/29‬ه ـ‬\n‫‪ ،‬أي بعــد انقضــاء عقــد االســتثمار بــن املدعيــة وبــن املالــك ‪ ،‬وألن‬\n‫مطالبــة املدعيــة للمدعــى عليــه باألجــرة فــرع عــن اســتمرار عقــد‬\n‫االســتثمار بينهــا وبــن املالــك للموقــع محــل النــزاع ‪ ،‬وبالتالــي فالصفــة‬\n‫يف هــذه الدعــوى منعدمــة يف املدعيــة ‪ ،‬ولقولــه تعالى‪»:‬يــا أيهــا الذيــن‬\n‫آمنــوا أوفــوا بالعقــود»‪ ،‬وحلديث‪»:‬املســلمون علــى شــروطهم» رواه‬\n‫الترمــذي وأبــو داوود‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت الدائــرة بــرد دعــوى‬\n‫املدعيــة يف مواجهــة املدعــى عليــه لعــدم ثبــوت اســتحقاقها يف املطالبــة‪،‬‬\n‫وصــرف النظــر عــن دعواهــا النعــدام الصفــة ‪ -‬وبعــرض احلكــم علــى‬\n\n\n                                                                                       ‫‪254‬‬\n\f      ‫املدعيــة قــررت عــدم القناعــة فأفهمــت بالتعليمــات ‪ -‬صــدق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......................‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪3435895‬‬\n      ‫وتاريــخ ‪1434/01/20‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34174581‬وتاريــخ‬\n      ‫‪1434/01/20‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1434/04/10‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 00‬وفيهــا حضــرت املدعيــة ‪ ..................‬ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........................‬واملعــرف بهــا مــن‬\n      ‫قبــل ابنهــا ‪ .........................‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .....................‬وادعــت علــى احلاضــر معهــا ‪ ..........................‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....................‬بصفتــه وكيــا ‬\n      ‫عــن ‪ ....................‬اجلنســية ســعودي مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ .....................‬بصفتــه وكيــا مبوجــب وكالــة رقــم ‪ 34248648‬بتاريــخ‬\n      ‫‪1434/2/30‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض‬\n      ‫ـوكل بهــا مــن ‪...................‬وعــن ‪ ..........................‬بالوكالــة رقــم‬\n                                                                                         ‫واملـ َ‬\n      ‫‪ 34248511‬يف ‪1434/2/30‬ه ـ وعــن ‪ .......................‬بالوكالــة رقــم‬\n      ‫‪ 34247666‬يف ‪1434/2/30‬ه ـ وعــن ‪ .................‬بالوكالــة رقــم‬\n      ‫‪ 34249676‬يف ‪1434/2/30‬ه ـ وعــن ‪ .....................‬بالوكالــة رقــم‬\n      ‫‪ 34244583‬يف ‪1434/2/30‬ه ـ وعــن ‪..................‬بالوكالــة رقــم‬\n      ‫‪ 34249829‬يف ‪1434/2/30‬ه ـ وعــن ‪ .........................‬بالوكالــة رقــم‬\n‫‪255‬‬\n\f‫‪ 34249872‬يف ‪1434/2/30‬ه ـ وعــن ‪ ..........................‬بالوكالــة رقــم‬\n‫‪ 34251868‬يف ‪1434/3/1‬ه ـ وجميعهــا صــادرة مــن كتابــة العــدل‬\n‫الثانيــة بجنــوب الريــاض بصفتهــم أعضــاء ‪.................‬بالســجل التجــاري‬\n‫رقــم ‪ .................‬وتاريــخ ‪1396/07/29‬ه ـ الصــادر باملرســوم امللكــي‬\n‫رقــم ‪ 46‬بتاريــخ ‪1395/06/12‬ه ـ ومبوجــب قــرار اجلمعيــة العامــة‬\n‫العاديــة «‪ »48‬يف ‪1434/02/12‬ه ـ وبصفتــه عضــو مجلــس اإلدارة يف‬\n‫‪ ...................‬بالسجل التجاري رقم ‪ .................‬بتاريخ ‪1396/07/29‬هـ‬\n‫ـاء علــى النظــام األساســي للشــركة املعتمد مبوجب‬            ‫الصــادر مــن جــدة بنـ ً‬\n‫املرســوم امللكــي رقــم ‪ 46‬يف ‪1395/6/12‬ه ـ وقــرار اجلمعيــة العامــة‬\n‫العاديــة (‪ )48‬يف ‪1434/2/12‬ه ـ وبصفــة البنــك شــريك يف أي شــركة‬\n‫‪ ،‬وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب‬\n‫الريــاض برقــم ‪ 34254204‬وتاريــخ ‪1434/3/1‬ه ـ قائلــة ‪ :‬إننــي كنــت‬\n‫مســتثمرة حملطــة يف حــي ‪ ...‬علــى طريــق ‪ ...‬مبحافظــة جــدة مــن مالكهــا‬\n‫مبوجــب عقــد إيجــار رقــم ‪ 46‬وتاريــخ ‪1426/5/1‬ه ـ محــرر علــى أوراق‬\n‫مؤسســة ‪ ، .................‬بينــي وبــن املالــك ‪ ........................‬اعتبــارا مــن‬\n‫تاريــخ ‪1426/5/1‬ه ـ وملــدة ثــاث ســنوات بأجــرة ســنوية قدرهــا مائتــان‬\n‫وعشــرون ألــف ريــال ‪ ،‬وقــد اســتأجر املدعــى عليــه موقعــا يف احملطــة‬\n‫محــل الدعــوى لغــرض إقامــة جهــاز الصــراف اآللــي ســيار ‪ ،‬وذلــك‬\n‫اعتبــارا مــن تاريــخ ‪2007/6/1‬م وملــدة خمــس ســنوات ميالديــة ‪ ،‬بأجــرة‬\n‫ســنوية قدرهــا ســبعون ألــف ريــال ‪ ،‬مبوجــب عقــد إيجــار موقــع مــؤرخ‬\n‫يف ‪2007/3/19‬م محــرر علــى أوراق بنــك ‪ ، ........‬ومت تخفيــض األجــرة‬\n‫السنوية لتكون مبلغا قدره ستون ألف ريال ‪ ،‬وقد تخلف املدعى عليه‬\n‫عــن دفــع أجــرة الســنة األخيــرة اعتبــارا مــن تاريــخ ‪2011/6/1‬م وحتــى‬\n\n\n                                                                                            ‫‪256‬‬\n\f      ‫تاريــخ ‪2012/5/31‬م وقدرهــا ســتون ألــف ريــال ‪ ،‬أطلــب إلــزام املدعــى‬\n      ‫عليــه بدفــع هــذا املبلــغ ‪ .‬هــذه دعــواي ‪ .‬ثــم أبــرزت املدعيــة صــورة مــن‬\n      ‫عقــد اإليجــار رقــم ‪ 46‬وتاريــخ ‪1426/5/1‬هــ‪ ،‬وصــورة مــن عقــد إيجــار‬\n      ‫موقــع املــؤرخ يف ‪2007/3/19‬م‪ ،‬ومت إرفاقهــا باملعاملــة ‪ ،‬وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه وكالــة قــال ‪ :‬أطلــب تزويــدي باملســتندات وإمهالــي‬\n      ‫للــرد‪ .‬ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يوم الســبت املوافق ‪1434/05/18‬هـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر ‪ ...................‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....................‬بصفتــه وكيــا ‬\n      ‫عــن املدعيــة ‪.....................‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ………………… مبوجــب الوكالــة رقــم ‪ 34254204‬وتاريــخ‬\n      ‫‪1434/03/01‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة شــمال جــدة‪،‬‬\n      ‫وحضــر املدعــي عليــه وكالــة ‪ ، .................‬وبســؤال املدعــى عليــه‬\n      ‫وكالــة عمــا طلــب اإلمهــال مــن أجلــه قــال ‪ :‬إن مــا ذكرتــه املدعيــة مــن‬\n      ‫عــدم دفــع موكلتــي ألجــرة الفتــرة مــن تاريــخ ‪2011/6/1‬م وحتــى تاريــخ‬\n      ‫‪2012/5/31‬م وقدرهــا ســتون ألــف ريــال فصحيــح ‪ ،‬وذلــك بتوجيــه‬\n      ‫مــن مالــك املوقــع بعــدم دفــع أجــرة للمدعيــة وذلــك لقيامــه بإنهــاء عقــد‬\n      ‫االســتثمار مــع املدعيــة ‪  ،‬وبــن املدعيــة ومالــك املوقع خــاف حول العقد‬\n      ‫وإنهائــه منظــورة لــدى املكتــب القضائــي رقــم ‪ ، 24‬ولــم تنتهــي الدعــوى‬\n      ‫بعــد ‪ ،‬وموكلتــي محتفظــة باألجــرة ملســتحقها بعــد إنتهــاء النــزاع بــن‬\n      ‫املدعيــة وبــن مالــك املوقــع ‪ ،‬وأطلــب إدخــال املالــك يف الدعــوى لتتضــح‬\n      ‫الصــورة ويظهــر املســتحق لهــا ‪ ،‬وموكلتــي علــى اســتعداد بدفعهــا‬\n      ‫ملســتحقها ‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال ‪ :‬الدعــوى التــي‬\n      ‫لــدى املكتــب رقــم ‪ 24‬هــي يف الضــرر الــذي وقــع علــى موكلتــي مــن‬\n\n\n‫‪257‬‬\n\f‫جــراء إخــاء املالــك ملوكلتــي مــن املوقــع ‪ .‬وبســؤال املدعــي وكالــة‬\n‫عــن عقــد االســتثمار الــذي بــن موكلتــه وبــن املالــك أبــرز صــورة منــه‬\n‫برقــم ‪ 46‬محــرر علــى أوراق مؤسســة ‪ ...........................‬ومــدة العقــد‬\n‫ثــاث ســنوات اعتبــارا مــن تاريــخ ‪1426/5/1‬ه ـ وحتــى ‪1429/5/1‬ه ـ‬\n‫وهــذا العقــد يتجــدد تلقائيــا بعــد موافقــة املالــك وإال يعتبــر ملغيــا ‪ ،‬ومت‬\n‫تزويــد املعاملــة بنســخة منــه ‪ ،‬وبســؤال املدعــي وكالــة هــل مت جتديــد‬\n‫العقــد بــن موكلتــه وبــن املالــك قــال ‪ :‬لــم يتــم بيننــا أي جتديــد كتابيــا‬\n‫‪ ،‬ولكــن املالــك وهــو ‪ ...........................‬كان يســتلم اإليجــار للفتــرة‬\n‫مــا بعــد انتهــاء املــدة األولــى للعقــد ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‬\n‫وكالــة قــال ‪ :‬أطلــب إدخــال املالــك لقطــع النــزاع ‪ .‬ثــم رفعــت اجللســة‬\n‫لطلــب املالــك ‪ ...................‬وإدخالــه يف الدعــوى ‪ .‬ويف يــوم الثالثــاء‬\n‫املوافق‪1434/08/09‬هـ افتتحت اجللسة الساعة ‪ 09 : 30‬وفيها حضرت‬\n‫املدعيــة ‪ .....................‬واملعــرف بهــا مــن قبــل زوجهــا ‪ ....................‬مينــي‬\n‫اجلنســية مبوجــب اإلقامــة رقــم ‪ ...................‬وحضراملدعــى عليــه وكالــة‬\n‫‪ ، ...............‬وحضــر ‪ .........................‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ .................‬بصفتــه وكيــا  عــن املالــك ‪........................‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....................‬أصالــة‬\n‫عــن نفســه وبوكالتــه الشــرعية عــن ‪ ......................‬و‪........................‬‬\n‫بالوكالــة الصــادرة مــن كتابــة العــدل مــن كتابــة العــدل الثانيــة شــمال‬\n‫محافظــة جــدة رقــم ‪ 45458‬وتاريــخ ‪1431/5/18‬ه ـ جلــد ‪ 9601‬مبوجب‬\n‫الوكالــة رقــم ‪ 41339‬وتاريــخ ‪1433/5/8‬ه ـ جلــد ‪ 11697‬الصــادرة مــن‬\n‫ذات اإلدارة ‪ ،‬وبســؤال املدعيــة عــن تاريــخ إخــاء املالــك لهــا مــن املوقــع‬\n‫قالــت ‪ :‬مت إخالئــي مــن املوقــع يف ‪1433/2/21‬ه ـ عــن طريــق احملافظــة‬\n\n\n                                                                                                 ‫‪258‬‬\n\f      ‫مبوجــب محضــر تســليم يف ‪1433/2/16‬ه ـ ‪ .‬وبســؤال املتداخــل وكالــة‬\n      ‫هــل مت جتديــد عقــد االســتثمار بــن موكلــك وبــن املدعيــة بعــد تاريــخ‬\n      ‫انتهــاء العقــد يف ‪1429/5/1‬ه ـ قــال ‪ :‬لقــد مت االتفــاق صلحــا بــن‬\n      ‫موكلــي وبــن املدعيــة يف ‪1431/6/29‬ه ـ علــى أن تبقــى املدعيــة يف‬\n      ‫املوقــع محــل النــزاع مــدة ســنة والــذي ينتهــي بــه العقــد للفتــرة الثانيــة مــن‬\n      ‫‪1429/5/1‬ه ـ وملــدة ثــاث ســنوات حتــى تاريــخ ‪1432/4/30‬ه ـ ثــم تقوم‬\n      ‫املدعيــة بإخــاء املوقــع ‪ ،‬وتســليمه ملوكلــي ‪ ،‬مبوجــب محضــر اتفاقيــة‬\n      ‫صلــح يف ‪1431/6/29‬ه ـ علــى أوراق وزارة الداخليــة (األمــن العــام) ‪،‬‬\n      ‫إال أن املدعيــة لــم تقــم بإخــاء العقــار ‪ ،‬فتوجــه موكلــي للمحافظــة‬\n      ‫ومت إخالئهــا عــن طريقهــم يف ‪1433/2/21‬ه ـ ‪ .‬وبعــرض ذلــك علــى‬\n      ‫املدعيــة قالــت ‪ :‬لــم يجــدد املالــك لــي العقــد بعــد تاريــخ ‪1432/4/30‬ه ـ‬\n      ‫‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وبنــاء علــى أن مطالبــة‬\n      ‫املدعيــة جتــاه املدعــى عليــه اعتبــارا مــن تاريــخ ‪2011/6/1‬م وحتــى‬\n      ‫تاريــخ ‪2012/5/31‬م ‪ ،‬وبنــاء علــى عقــد االســتثمار بــن املدعيــة واملالــك‬\n      ‫رقــم ‪ 46‬احملــرر علــى أوراق مؤسســة ‪ .......................‬ومــدة العقــد ثــاث‬\n      ‫ســنوات اعتبــارا مــن تاريــخ ‪1426/5/1‬ه ـ وحتــى ‪1429/5/1‬هــ  ‪ ،‬وبنــاء‬\n      ‫علــى إقــرار املدعيــة بــأن هــذا العقــد يتجــدد تلقائيــا بعــد موافقــة املالــك‬\n      ‫وإال يعتبــر ملغيــا ‪ ،‬وبنــاء علــى إقــرار املتداخــل وكالــة بتجديــد موكلــه‬\n      ‫للعقــد حتــى تاريــخ ‪1432/4/30‬ه ـ ‪ ،‬وبنــاء علــى محضــر اتفاقيــة صلــح‬\n      ‫يف ‪1431/6/29‬ه ـ احملــررة بــن املالــك واملدعيــة واملتضمــن اســتمرار‬\n      ‫العقــد بينهمــا حتــى تاريــخ ‪1432/4/30‬ه ـ ‪ ،‬وبنــاء علــى إقــرار املدعيــة‬\n      ‫جوابــا علــى مــا قــرره املتداخــل وكالــة مــن عــدم جتديــد عقــد االســتثمار‬\n      ‫بعــد تاريــخ ‪1432/4/30‬ه ـ ‪ ،‬وبنــاء علــى أن بدايــة تاريــخ مطالبــة املدعية‬\n\n\n‫‪259‬‬\n\f‫للمدعــى عليــه يف ‪2011/6/1‬م ‪ ،‬وهــو يوافــق ‪1432/6/29‬ه ـ ‪ ،‬أي‬\n‫بعــد انقضــاء عقــد االســتثمار بــن املدعيــة وبــن املالــك ‪ ،‬وألن مطالبــة‬\n‫املدعيــة للمدعــى عليــه باألجــرة فــرع عــن اســتمرار عقــد االســتثمار‬\n‫بينهــا وبــن املالــك للموقــع محــل النــزاع ‪ ،‬وبالتالــي فالصفــة يف هــذه‬\n‫الدعــوى منعدمــة يف املدعيــة ‪ ،‬ولقولــه تعالــى (يــا أيهــا الذيــن آمنــوا‬\n‫أوفــوا بالعقــود)‪ ،‬وحلديــث (املســلمون علــى شــروطهم) رواه الترمــذي‬\n‫وأبــو داوود ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت بــرد دعــوى املدعيــة‬\n‫‪ ...................‬يف مواجهــة املدعــى عليــه ‪ ..............‬لعــدم ثبــوت اســتحقاقها‬\n‫يف املطالبــة مبــا ورد يف الدعــوى النقضــاء عقــد االســتثمار بينهــا وبــن‬\n‫املالــك للموقــع محــل النــزاع ‪ ،‬وصرفــت النظــر عــن دعواهــا النعــدام‬\n‫الصفــة يف املدعيــة باملطالبــة مبــا ورد يف الدعــوى ‪ .‬وبــه حكمــت ‪.‬‬\n‫وبــه قنــع املدعــى عليــه وكالــة ‪ ،‬وقــررت املدعيــة االعتــراض ‪ ،‬وجــرى‬\n‫تســليمه نســخة مــن احلكــم وإفهامــه بــأن لــه احلــق يف االعتــراض عليــه‬\n‫خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف االعتــراض ‪ ،‬واكتســب‬\n‫احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة  ‪ .10 : 00‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                ‫‪1434/08/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة ففــي يــوم اخلميــس املوافــق‪ 1435/01/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 8 : 45‬وفيهــا قــد عــادت املعاملــة مــن محمكــة‬\n\n\n                                                                                           ‫‪260‬‬\n\f        ‫االســتئناف بخطــاب رئيســها رقــم ‪ 34174581‬وتاريــخ ‪ 1435/1/2‬ه ـ‬\n        ‫ومرفــق بهــا القــرار رقــم ‪ 34387491‬وتاريخ ‪1434/12/25‬هـ ومضمونه‬\n        ‫مــا يلــي ( وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n        ‫باألكثريــة املوافقــة علــى احلكــم ‪ ،‬وحتــى ال يخفــى جــرى إثباتــه ‪.‬‬\n        ‫وأقفلــت اجللســة الســاعة ‪  8 : 55‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1435/01/11‬ه ـ‬\n        ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد‬\n        ‫ج ــرى م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف‬\n        ‫محكمــة االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا‬\n        ‫احلكــم الصــادر مــن فضيلــة الشــيخ‪ .............................../‬القاضــي‬\n        ‫باحملكمــة العامــة مبحافظــة جــدة واملســجل بع ــدد‪ 34293038‬وتاريــخ‬\n        ‫‪1434/8/9‬هـ‪،‬املتضمــن دعــوى ‪   ..................‬ضــد ‪.......................‬‬\n      ‫احملكــوم في ــه مبــا دون باطنه‪،‬وبدراس ــة احلكــم وص ــورة ضبط ــه  ‬\n        ‫والالئحــة االعتراضيــة تق ــرر باألكثريــة  املوافق ــة عل ــى احلكــم‪،‬واهلل‬\n           ‫املوفــق‪ .‬وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪261‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":253,"source_page_end":261,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b57550f43f7ddb1442188c0cc77cfb091a6aca58bf9ff2ab4fde3271fcfbe06b","normalized_text_hash":"ecee7bc6eb1b1e8a477f64295a8a89a28caf5a7bf2f523145a6076e12aaec398","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p253-34293038"},{"id":"92a707fd-5aae-5e87-a1c7-8638813d16bc","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء العقار لعدم التجديد -اإلقرار بعدم القيام بإخطار مالك العقار بالتجديد حسب شروط العقد -احلكم بإخالء العني املؤجرة وتسليم عقار ملالكه كما استلمه .","document_number":"3438657","case_number":"33557277","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/17","year":"1434","subject":"إجارة -إخاء العقار لعدم التجديد -اإلقرار بعدم القيام بإخطار مالك العقار بالتجديد حسب شروط العقد -احلكم بإخالء العني املؤجرة وتسليم عقار ملالكه كما استلمه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/17 :‬هـ  ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪3438657 :‬‬\n                    ‫َر ْق ُم الدعوى‪33557277 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34281969‬تاريخه‪1434/7/29 :‬هـ‬\n\n\n\n‫إجــارة ‪ -‬إخــاء العقــار لعــدم التجديــد ‪ -‬اإلقــرار بعــدم القيــام بإخطــار‬\n‫مالــك العقــار بالتجديــد حســب شــروط العقــد ‪ -‬احلكــم بإخالء العني‬\n                          ‫املؤجــرة وتســليم عقــار ملالكــه كمــا اســتلمه ‪.‬‬\n\n\n\n\n                                                 ‫القاعدة الفقهية « ال عذر ملن أقر»‬\n\n\n\n\n‫ادعــى املدعــى وكالــة بــأن املدعــى عليــه اســتأجر مــن موكلــه شــقة يف‬\n‫عمــارة ميلكهــا بأجــرة ســنوية قدرهــا اربعــة وعشــرون ألــف ريــال ملــدة‬\n‫ســنة مــن ‪ 1430/7/1‬ه ـ وحيــث إن املدعــى عليــه مياطــل يف الســداد فقــد‬\n‫طلــب املدعــى وكالــة الــزام املدعــى عليــه باإلخالء ‪ -‬اجــاب املدعى عليه‬\n‫باملصادقــة علــى الدعــوى وقــرر انــه مســتأجر العقــار مــن تســع ســنوات‬\n‫ولكــن املدعــى أخــذ يرفــع يف األجــرة ولــم يعمــل صيانــة للعقــار كمــا ان‬\n‫العقــد يتجــدد تلقائيــا ورفــض املدعــى عليــه االخــاء ‪ -‬مت اطــاع حاكــم‬\n‫القضيــة علــى العقــد ‪ -‬مــن ضمــن شــروط العقــد ان علــى املســتأجر‬\n‫اخبــار املؤجــر بالتجديــد قبــل نهايــة املــدة القدميــة بشــهر ‪  -‬قــرر املدعــى‬\n‫عليــه انــه لــم يخبــر املدعــى بالتجديــد ‪ -‬لألســباب املرصــودة يف نــص‬\n‫القضيــة وللقاعــدة الفقهيــة ال عــذر ملــن اقــر صــدر احلكــم علــى املدعــى‬\n                                                                                       ‫‪262‬‬\n\f      ‫عليــه بإخــاء الشــقة وتســليمها للمدعــى كمــا اســتلمها ‪ -‬قــرر املدعــى‬\n      ‫عليــه عــدم القناعــة ‪ -‬صــدر قــرار محكمــة االســتئناف باملصادقــة علــى‬\n                                                                        ‫احلكــم‪.‬‬\n\n\n\n\n        ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد فلــدي أنــا‬\n        ‫القاضــي يف احملكمــة العامــة بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا‬\n        ‫مــن فضيلــة رئيــس احملكمــة العامــة بالدمــام برقــم ‪ 33557277‬وتاريــخ‬\n        ‫‪ 1433/09/02‬هــ   املقيــدة باحملكمــة برقــم ‪ 331635977‬وتاريــخ‬\n        ‫‪ 1433/09/02‬هــ  ففــي يــوم األحــد ‪ 1433/11/21‬ه ـ افتتحــت اجللســة‬\n        ‫الســاعة العاشــرة وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n        ‫رقــم وكيــا عــن مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدمــام‬\n        ‫الثانيــة برقــم ‪ 33206565‬وتاريــخ ‪1433/8/3‬ه ـ والتــي تخولــه املرافعــة‬\n      ‫واملدافعــة وادعــى علــى الغائــب عــن مجلــس احلكــم الــذي تبلــغ لشــخصه  ‬\n        ‫قائــا يف دعــواه إن الغائــب عــن مجلــس احلكــم اســتأجر مــن موكلــي‬\n        ‫شــقة يف عمارته الواقعة يف حي ‪ ...‬بأجرة ســنوية قدرها أربعة وعشــرين‬\n        ‫ألــف ريــال تبــدأ بتاريــخ ‪1430/7/1‬ه ـ ملدة ســنة ومت جتديد العقد بتاريخ‬\n        ‫‪1433/12/30‬هـ وألن املدعى عليه مياطل يف الســداد وأخشــى أن مياطل‬\n        ‫يف اإلخــاء لــذا أطلــب إلزامــه بإخــاء الشــقة بتاريــخ ‪1433/12/30‬ه ـ‬\n        ‫وتســليمها ملوكلــي كمــا اســتلمها هــذه دعــواي ‪ ،‬فجــرى االطــاع‬\n        ‫علــى صــك ملكيــة العقــار رقــم ‪ 4/1/128‬يف ‪1421/7/6‬ه ـ الصــادر‬\n        ‫مــن كتابــة العــدل األولــى بالدمــام واملتضمــن متلــك باطنــه للمدعــي‬\n        ‫أصالــة فطلبــت مــن املدعــي وكالــة البينــة علــى ذلــك ‪،‬ويف يــوم الســبت‬\n‫‪263‬‬\n\f‫‪1434/02/16‬هــ  حضــر املدعــي وكالــة املدونــة هويتــه ووكالتــه فيمــا‬\n‫ســبق كمــا حضــر  املدعــى عليــه مينــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم ‪ ...‬وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي وكالــة‬\n‫ماذكــره املدعــي وكالــة مــن كونــي مســتأجرا للشــقة املذكــورة هــذا‬\n‫صحيــح وبدايــة اإليجــار منــذ تســع ســنوات تقريبــا ولكــن املدعــي أخــذ‬\n‫يرفــع األجــرة ولــم يعمــل صيانــة للشــقة وأنــا أرفــض ذلــك لعــدم الصيانــة‬\n‫كمــا أن مــدة العقــد ســنة تتجــدد تلقائيــا وأرفــض إخــاء الشــقة ألننــي‬\n‫منــذ مــدة وأنــا فيهــا وقــد عملــت فيهــا بعــض اإلصالحــات واإلضافــات‬\n‫علمــا أن العقــد يتجــدد بدايــة كل ســنة هجريــة هكــذا أجــاب فطلبــت‬\n‫مــن الطرفــن صــورة العقــد فابــرز املدعــي وكالــة نســخة كربونــه‬\n‫علــى مطبوعــات مكتــب ‪ ...‬العقــاري بتاريــخ ‪2009/7/4‬م وفيــه املؤجــر‬\n‫واملســتأجر كمــا ذكرهــا الطرفــان واألجــرة واحــد وعشــرون الــف‬\n‫ريــال تبــدأ بتاريــخ ‪1430/7/1‬ه ـ ومــن ضمــن شــروطه أن علــى املســتأجر‬\n‫أن يخبــر املؤجــر قبــل انتهــاء املــدة القدميــة بشــهر واحــد فيمــا إذا كان‬\n‫يريــد التجديــد ويف حــال عــدم رغبــة املؤجــر التجديــد فعلــى املســتأجر أن‬\n‫يخلــي املأجــور يف آخــر يــوم مــن االتفاقيــة إذا لــم يرغــب املؤجــر التجديــد‪.‬‬\n‫وبعرضــه علــى املدعــى عليــه صــادق عليــه فســألته هــل طلــب مــن‬\n‫املدعــي أصالــة أو وكيلــه التجديــد للســنة اجلديــدة التــي تبــدأ بتاريــخ‬\n‫‪1434/1/1‬ه ـ قــال ال ألن األصــل أن العقــد يتجــدد تلقائيــا فبنــاء علــى‬\n‫ماتقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه وألنــه ال عــذر‬\n‫ملــن أقــر وألن الشــرط واضــح وصريــح يف أن العقــد يتجــدد إذا أخبــر‬\n‫املســتأجر املؤجــر بذلــك وأقــر املدعــى عليــه بأنــه لــم يقــم بإخبــاره لــذا‬\n‫فقــد ثبــت لــدي اســتحقاق املدعــي ملــا يدعيــه وألزمــت املدعــى عليــه‬\n\n\n                                                                                       ‫‪264‬‬\n\f        ‫بإخــاء الشــقة منــذ تاريــخ ‪1433/12/30‬ه ـ وتســليمها للمدعــي كمــا‬\n        ‫اســتلمها وبــه حكمــت وبعرضــه عليهمــا قنــع املدعــي وكالــة ولــم يقنــع‬\n        ‫املدعــى عليــه وطلــب االســتئناف مســتعدا بتقــدمي الئحــة اعتراضيــة‬\n        ‫فأجيــب لطلبــه وأفهــم مبراجعــة احملكمــة يــوم األربعــاء ‪1434/2/20‬ه ـ‬\n        ‫الســتالم نســخة مــن احلكــم وتقــدمي االعتــراض عليــه خــال ثالثــن يومــا‬\n        ‫مــن تاريــخ حتديــد موعــد اســتالم النســخة وإذا مضــت املــدة احملــددة‬\n        ‫لالعتــراض ولــم يقــدم شــيئا ســقط حقــه يف االعتــراض واكتســب‬\n      ‫احلكــم القطعيــة وكانــت ســاعة احلكــم احلاديــة عشــرة ة والنصــف‪  .‬‬\n        ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف  ‪1434/02/16‬هــ‪.‬‬\n        ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n        ‫أمــا بعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى يف‬\n        ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n        ‫فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام برقــم ‪331635977‬‬\n        ‫وتاريــخ ‪1434/6/12‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪341518190‬‬\n        ‫وتاريــخ ‪1434/6/24‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n        ‫باحملكمة الشــيخ‪ ... /‬املســجل برقم ‪ 3438657‬وتاريخ ‪1434/2/17‬هـ‬\n        ‫اخلــاص بدعــوى‪ .../‬ضــد‪ (... /‬ميانــي اجلنســية ) يف قضيــة حقوقيــة وقــد‬\n        ‫تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n        ‫قررنــا‬‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة ّ‬\n        ‫املصادقــة علــى احلكــم ‪ ،‬مــع تنبيــه فضيلتــه إلــى ضــرورة تعديــل العبــارة‬\n        ‫ـاض اليســوغ واملتعـ ّـن إثبــات‬\n                                      ‫يف احلكــم ؛ ألن احلكــم باإلخــاء بتاريــخ مـ ٍ‬\n        ‫انتهــاء العقــد بتاريــخ ‪1433/12/30‬ه ـ ويكــون احلكــم باإلخــاء فــور ًا‬\n\n\n‫‪265‬‬\n\f‫بتاريــخ جلســة احلكــم ‪ ،‬فعلــى فضيلتــه إجــراء التعديل قبــل بعث املعاملة‬\n     ‫للتنفيــذ ‪ ،‬ولبيانــه حــرر يف ‪1434/7/29‬ه ـ ‪ ،‬واهلل ولــي التوفيــق‪.‬‬\n\n\n\n\n                                                                               ‫‪266‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2e380a2f-49d8-5199-a84b-d3b37251547c","source_page_start":262,"source_page_end":266,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"74e3deea546e1701195da8869588b26548ce91c3d4d2bd330f72486ca2d30bbe","normalized_text_hash":"59bfeaa5ca82e43585f487a0b7edca1af6c3e5c2ce0d234f8c2acb6f7078c84b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v6-p262-3438657"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

